/* Ezber kartları: TYT (2018 MEB programı, 9–10. sınıf). Herkes için ortak içerik; flashcards.js okur.
   Biçim: [{subject, units:[{id, name, cards:[{f: ön yüz, b: arka yüz}]}]}] */
window.ODAK_CARDS = [{"subject":"Edebiyat","units":[]},{"subject":"Fizik","units":[{"id":"fiz-1","name":"Fizik Bilimine Giriş","cards":[{"f":"Fizik bilimi neyi inceler?","b":"Evrendeki olayları ve doğanın işleyişini yasalarla açıklayan temel bilim dalıdır."},{"f":"Fiziğin alt dalları nelerdir?","b":"Mekanik, termodinamik, elektromanyetizma, optik, katıhal fiziği, atom fiziği, nükleer fizik, yüksek enerji ve plazma fiziği."},{"f":"Mekanik hangi konularla ilgilenir?","b":"Cisimlerin hareketi, kuvvetler ve denge durumlarıyla ilgilenir."},{"f":"Termodinamik hangi konularla ilgilenir?","b":"Isı, sıcaklık ve enerji dönüşümleriyle ilgilenir."},{"f":"Elektromanyetizma neyi inceler?","b":"Elektrik ve manyetizma olaylarını ve aralarındaki ilişkiyi inceler."},{"f":"Optik neyi inceler?","b":"Işığın davranışını; yansıma, kırılma, görüntü oluşumu gibi olayları inceler."},{"f":"Atom fiziği ile nükleer fizik arasındaki fark nedir?","b":"Atom fiziği atomun yapısını, nükleer fizik atom çekirdeğiyle ilgili olayları (fisyon, füzyon) inceler."},{"f":"Plazma nedir?","b":"Gazın çok yüksek sıcaklıkta iyonlaşmış, elektrik yüklü tanecikler içeren dördüncü hâlidir."},{"f":"Fiziğin felsefeyle ilişkisine bir örnek nedir?","b":"Evrenin doğası ve bilginin kaynağı gibi sorular hem fizik hem felsefenin ilgi alanına girer."},{"f":"Fiziğin biyolojiyle ilişkisine bir örnek nedir?","b":"Kalp atışının elektriksel sinyalleri veya gözün optik sistemi gibi konular biyofizikle açıklanır."},{"f":"Fiziğin sanatla ilişkisine bir örnek nedir?","b":"Perspektif çiziminde ışığın davranışı ve müzikte ses dalgalarının frekans-tını ilişkisi örnek verilebilir."},{"f":"Fiziğin sporla ilişkisine bir örnek nedir?","b":"Bir atletin sıçrama açısı veya topun hareketi kuvvet ve hareket yasalarıyla açıklanır."},{"f":"Temel büyüklük nedir?","b":"Başka büyüklüklere bağlı olmayan, doğrudan tanımlanan büyüklüktür (uzunluk, kütle, zaman gibi)."},{"f":"Türetilmiş büyüklük nedir?","b":"Temel büyüklüklerin birleşiminden elde edilen büyüklüktür (hız, kuvvet, alan gibi)."},{"f":"SI birim sisteminde bazı temel büyüklüklerin birimleri nelerdir?","b":"Uzunluk (metre), kütle (kilogram), zaman (saniye), sıcaklık (kelvin), akım (amper)."},{"f":"Skaler büyüklük nedir?","b":"Sadece sayısal değer ve birimle tanımlanan, yönü olmayan büyüklüktür (kütle, sıcaklık, sürat gibi)."},{"f":"Vektörel büyüklük nedir?","b":"Büyüklüğün yanında yönü de belirtilmesi gereken büyüklüktür (hız, kuvvet, yer değiştirme gibi)."},{"f":"SI birim sistemi neden kullanılır?","b":"Bilimsel ölçümlerde dünya genelinde ortak bir dil sağlamak için kullanılan uluslararası birim sistemidir."},{"f":"MEB programında sayılan bilim araştırma merkezleri hangileridir?","b":"TÜBİTAK, TAEK, ASELSAN, CERN, NASA, ESA."},{"f":"TÜBİTAK nedir?","b":"Türkiye'nin bilimsel ve teknolojik araştırmalarını desteklemek için kurulan resmi kurumudur."},{"f":"CERN nedir?","b":"Avrupa'da kurulu, parçacık fiziği alanında büyük hızlandırıcılarla araştırma yapan uluslararası merkezdir."},{"f":"NASA ve ESA hangi alanda çalışır?","b":"NASA (ABD) ve ESA (Avrupa), uzay araştırmaları ve uzay teknolojileri geliştiren kurumlardır."},{"f":"Bilimsel araştırmalarda etik ilkelere uymak neden önemlidir?","b":"Verilerin dürüst paylaşılması ve başkalarının emeğine saygı, bilimin güvenilirliğini korur."},{"f":"Fiziksel niceliklerin sınıflandırılmasında iki temel ayrım nedir?","b":"Temel–türetilmiş ayrımı ve skaler–vektörel ayrımıdır."}]},{"id":"fiz-2","name":"Madde ve Özellikleri","cards":[{"f":"Kütle nedir?","b":"Bir cismin sahip olduğu madde miktarının ölçüsüdür; bulunduğu yere göre değişmez."},{"f":"Hacim nedir?","b":"Bir cismin uzayda kapladığı boşluğun ölçüsüdür."},{"f":"Kütlenin yaygın birimleri nelerdir?","b":"Miligram, gram, kilogram ve tondur."},{"f":"Hacmin yaygın birimleri nelerdir?","b":"mL, L, cm³, dm³ ve m³'tür."},{"f":"Özkütle nasıl tanımlanır?","b":"Bir maddenin birim hacminin kütlesidir; d = kütle / hacim formülüyle bulunur."},{"f":"Özkütlenin birimi nedir?","b":"SI'da kg/m³'tür; günlük kullanımda sıkça g/cm³ de kullanılır."},{"f":"Saf maddelerin özkütlesi nasıl bir özelliktir?","b":"Sabit sıcaklık ve basınçta her saf madde için karakteristik (ayırt edici) bir değerdir."},{"f":"Karışımların özkütlesi neye göre değişir?","b":"Karışımı oluşturan maddelerin oranına göre değişir; karışımın karakteristik sabit bir özkütlesi yoktur."},{"f":"Archimedes özkütle alanında neyle bilinir?","b":"Bir tacın saf altından yapılıp yapılmadığını, cismi suya batırarak taşan su hacminden anlamıştır."},{"f":"el-Hazini'nin özkütle bilimine katkısı nedir?","b":"Maddelerin özkütlesini ölçmek için hassas teraziler ve yöntemler geliştiren Ortaçağ İslam bilginidir."},{"f":"Özkütleden hangi meslek alanlarında faydalanılır?","b":"Kuyumculuk, porselen yapımı ve ebru sanatı gibi alanlarda faydalanılır."},{"f":"Kuyumculukta özkütle nasıl kullanılır?","b":"Bir metalin gerçek altın olup olmadığı, özkütlesi bilinen saf altınla karşılaştırılarak anlaşılabilir."},{"f":"Dayanıklılık neyi ifade eder?","b":"Bir cismin dış etkilere (basınç, yük gibi) karşı biçimini koruyabilme direncidir."},{"f":"Dayanıklılık hangi geometrik orana bağlıdır?","b":"Cismin kesit alanının hacmine oranına bağlıdır; bu oran arttıkça dayanıklılık artar."},{"f":"Adezyon nedir?","b":"Farklı cins moleküller arasındaki çekim kuvvetidir; örneğin suyun cam yüzeye yapışması."},{"f":"Kohezyon nedir?","b":"Aynı cins moleküller arasındaki çekim kuvvetidir; örneğin su moleküllerinin birbirini çekmesi."},{"f":"Su cam üzerinde neden yayılır ama cıva yayılmaz?","b":"Suda adezyon kohezyondan büyüktür (yayılır); cıvada kohezyon adezyondan büyüktür (damlacık kalır)."},{"f":"Yüzey gerilimi nedir?","b":"Sıvı yüzeyindeki moleküllerin kohezyon kuvvetiyle bir zar gibi davranmasıdır."},{"f":"Yüzey gerilimine bir günlük hayat örneği nedir?","b":"Bazı böceklerin su üzerinde batmadan yürüyebilmesi veya bir iğnenin su yüzeyinde durabilmesi."},{"f":"Yüzey gerilimini hangi etkenler azaltır?","b":"Sıcaklığın artması ve deterjan gibi yüzey aktif maddelerin eklenmesi yüzey gerilimini azaltır."},{"f":"Kılcallık nedir?","b":"Adezyon-kohezyon dengesine bağlı olarak sıvının ince borularda yükselmesi veya alçalmasıdır."},{"f":"Kılcallığa bir doğa örneği nedir?","b":"Bitkilerde suyun kökten gövde ve yapraklara kılcal borularla taşınmasıdır."},{"f":"Kılcal boruda su yükselir, cıva neden alçalır?","b":"Suda adezyon kohezyondan büyük olduğu için yükselir; cıvada kohezyon adezyondan büyük olduğu için alçalır."}]},{"id":"fiz-3","name":"Hareket ve Kuvvet","cards":[{"f":"Öteleme hareketi nedir?","b":"Cismin her noktasının aynı anda aynı yönde, birbirine paralel yollar izlediği harekettir."},{"f":"Dönme hareketi nedir?","b":"Cismin sabit bir eksen etrafında döndüğü harekettir."},{"f":"Titreşim hareketi nedir?","b":"Bir cismin denge konumu etrafında tekrarlanan ileri geri hareketidir."},{"f":"Konum nedir?","b":"Bir cismin, seçilen bir referans noktasına göre bulunduğu yerdir."},{"f":"Alınan yol ile yer değiştirme arasındaki fark nedir?","b":"Yol, izlenen gerçek mesafenin (skaler) toplamıdır; yer değiştirme, başlangıç ve bitiş arasındaki vektörel mesafedir."},{"f":"Sürat ile hız arasındaki fark nedir?","b":"Sürat skaler bir büyüklüktür (sadece değer); hız vektöreldir (değer ve yön içerir)."},{"f":"Ortalama hız nasıl tanımlanır?","b":"Toplam yer değiştirmenin, bu yer değiştirmenin gerçekleştiği toplam zamana oranıdır."},{"f":"Anlık hız nedir?","b":"Bir cismin belirli bir andaki hızıdır."},{"f":"İvme nedir?","b":"Hızın birim zamandaki değişim miktarıdır."},{"f":"İvme ile hız aynı yönde olursa ne olur, zıt yönde olursa ne olur?","b":"Aynı yönde ise cisim hızlanır; zıt yönde ise cisim yavaşlar."},{"f":"Hareketin göreli olması ne demektir?","b":"Bir cismin hareketli mi durgun mu olduğu, seçilen referans noktasına göre değişebilir."},{"f":"Kuvvet nedir?","b":"Bir cismin hareket durumunu (hızını veya yönünü) değiştirebilen veya şeklini bozabilen etkidir."},{"f":"Temas gerektiren kuvvete örnek nedir?","b":"İtme, çekme ve sürtünme kuvveti; cisimlerin doğrudan birbirine değmesini gerektirir."},{"f":"Temas gerektirmeyen kuvvete örnek nedir?","b":"Kütle çekim kuvveti, elektriksel kuvvet ve manyetik kuvvet; cisimler değmeden etkileşir."},{"f":"Doğadaki dört temel kuvvet nedir?","b":"Kütle çekim kuvveti, elektromanyetik kuvvet, güçlü nükleer kuvvet ve zayıf nükleer kuvvettir."},{"f":"Kütle çekim kuvveti hangi değişkenlere bağlıdır?","b":"Cisimlerin kütlelerine ve aralarındaki uzaklığa bağlıdır."},{"f":"Dengelenmiş kuvvetlerin etkisindeki cisim nasıl hareket eder?","b":"Net kuvvet sıfır olduğundan cisim durgun kalır veya sabit hızla düz bir çizgide hareket etmeye devam eder."},{"f":"Dengelenmemiş (net) kuvvetin etkisindeki cisme ne olur?","b":"Cisim ivme kazanır; hızı büyüklük veya yön olarak değişir."},{"f":"Eylemsizlik ilkesi (Newton'ın 1. yasası) ne der?","b":"Bir cisme net bir kuvvet etki etmediği sürece cisim hareket durumunu (durgunluk veya sabit hız) korur."},{"f":"Newton'ın 2. yasası neyi ilişkilendirir?","b":"Bir cisme etki eden net kuvveti, cismin kütlesi ve kazandığı ivme ile ilişkilendirir."},{"f":"Etki-tepki yasası (Newton'ın 3. yasası) ne der?","b":"Bir cisim başka bir cisme kuvvet uygularsa, ikinci cisim de birincisine eşit büyüklükte zıt yönlü kuvvet uygular."},{"f":"İbn-i Sina'nın hareket konusuna katkısı nedir?","b":"Eylemsizliğe yakın fikirler öne sürerek Newton'dan önce hareketle ilgili önemli gözlemler yapmıştır."},{"f":"Sürtünme kuvveti nedir?","b":"Temas hâlindeki iki yüzeyin birbirinin hareketine karşı gösterdiği dirençtir."},{"f":"Statik sürtünme ile kinetik sürtünme arasındaki fark nedir?","b":"Statik sürtünme cisim harekete geçmeden önceki direnç, kinetik sürtünme hareket sırasındaki dirençtir; statik genelde kinetikten büyüktür."},{"f":"Sürtünme kuvvetinin bir avantajı ve bir dezavantajı nedir?","b":"Avantaj: yürüyebilme ve araç lastiklerinin yol tutması. Dezavantaj: makine parçalarının aşınması ve enerji kaybı."}]},{"id":"fiz-4","name":"Enerji","cards":[{"f":"Fizikte iş nasıl tanımlanır?","b":"Bir kuvvetin, uygulandığı cismi kendi doğrultusunda yer değiştirmesi sonucu yaptığı etkidir."},{"f":"Fiziksel iş ile günlük dildeki iş arasındaki fark nedir?","b":"Fizikte kuvvet cismi hareket ettirmezse iş sıfırdır; günlük dilde harcanan her çaba iş sayılır."},{"f":"Güç nedir?","b":"Birim zamanda yapılan işin miktarıdır."},{"f":"İş ile enerji arasındaki ilişki nedir?","b":"İş yapmak, bir cisme veya sistemden enerji aktarmak ya da almak anlamına gelir."},{"f":"Kinetik enerji nedir?","b":"Hareket eden bir cismin sahip olduğu enerjidir; kütle ve hıza bağlıdır."},{"f":"Yer çekimi potansiyel enerjisi nedir?","b":"Bir cismin bulunduğu konum (yükseklik) nedeniyle sahip olduğu enerjidir."},{"f":"Esneklik potansiyel enerjisi nedir?","b":"Bir yayın veya esnek cismin sıkışması ya da gerilmesi sonucu depoladığı enerjidir."},{"f":"Mekanik enerji nedir?","b":"Bir sistemin kinetik enerjisi ile potansiyel enerjisinin (yer çekimi + esneklik) toplamıdır."},{"f":"Enerjinin korunumu ilkesi ne der?","b":"Enerji yoktan var edilemez, var olan enerji yok edilemez; sadece bir biçimden diğerine dönüşür."},{"f":"Sürtünme enerji korunumunu nasıl etkiler?","b":"Sürtünme nedeniyle enerjinin bir kısmı ısıya dönüşür; enerji kaybolmaz, sadece istenmeyen biçime dönüşür."},{"f":"Bir enerji dönüşümüne örnek veriniz.","b":"Elektrik enerjisinin bir ampulde ışık ve ısı enerjisine dönüşmesi."},{"f":"Canlılar fiziksel iş yapmadan enerji harcayabilir mi?","b":"Evet; örneğin ağır bir cismi sabit tutarken kas gerginliği nedeniyle enerji harcanır ama fiziksel iş sıfırdır."},{"f":"Verim nedir?","b":"Bir sisteme verilen enerjinin, yararlı işe dönüşen kısmının oranıdır."},{"f":"Verim neden hiçbir zaman %100 olamaz?","b":"Enerjinin bir kısmı her zaman sürtünme veya ısı gibi istenmeyen biçimlere kaçınılmaz olarak dönüşür."},{"f":"Enerji kimlik belgesi neyi gösterir?","b":"Bir binanın veya sistemin enerji tasarrufu ve verimlilik düzeyini gösteren belgedir."},{"f":"Yenilenebilir enerji kaynağına örnek veriniz.","b":"Güneş enerjisi, rüzgâr enerjisi, hidroelektrik ve jeotermal enerji."},{"f":"Yenilenemez enerji kaynağına örnek veriniz.","b":"Kömür, petrol, doğal gaz ve nükleer yakıt (uranyum)."},{"f":"Nükleer enerji neden yenilenemez kaynak sayılır?","b":"Kullanılan uranyum gibi yakıtlar sınırlıdır ve insan ömrü ölçeğinde yenilenmez."},{"f":"Enerji kaynağı seçiminde hangi kriterler göz önünde bulundurulur?","b":"Maliyet, erişilebilirlik, üretim kolaylığı, toplumsal, teknolojik ve çevresel etkiler."},{"f":"Enerji tasarrufu neden önemlidir?","b":"Sınırlı kaynakların daha uzun süre kullanılabilmesini ve çevresel etkilerin azalmasını sağlar."},{"f":"Mekanik iş hesaplanırken hangi kuvvet bileşeni dikkate alınır?","b":"Yalnızca hareketle aynı doğrultuda olan kuvvet bileşeni dikkate alınır."},{"f":"Yer çekimi potansiyel enerjisi hangi değişkenlere bağlıdır?","b":"Cismin kütlesine, bulunduğu yüksekliğe ve yer çekimi ivmesine bağlıdır."},{"f":"Esneklik potansiyel enerjisi hangi değişkenlere bağlıdır?","b":"Yayın esneklik (yay) sabitine ve yayın sıkışma/gerilme miktarına bağlıdır."},{"f":"Fiziksel güç ile günlük dildeki güç kavramı aynı mıdır?","b":"Hayır; fizikte güç birim zamanda yapılan iştir, günlük dilde güç genellikle kuvvet veya kudret anlamında kullanılır."}]},{"id":"fiz-5","name":"Isı ve Sıcaklık","cards":[{"f":"Isı nedir?","b":"Sıcaklık farkı nedeniyle bir maddeden diğerine aktarılan enerjidir."},{"f":"Sıcaklık nedir?","b":"Bir maddenin taneciklerinin ortalama kinetik enerjisinin göstergesidir."},{"f":"Isı ile sıcaklık birbirinden nasıl ayrılır?","b":"Isı transfer edilen enerji miktarıdır (joule); sıcaklık bir durumun ölçüsüdür (derece, kelvin)."},{"f":"İç enerji nedir?","b":"Bir maddeyi oluşturan taneciklerin toplam kinetik ve potansiyel enerjisidir."},{"f":"Sıcaklık birimleri nelerdir?","b":"Celsius (°C), Fahrenheit (°F) ve Kelvin (K)."},{"f":"Termometre çeşitlerine örnek veriniz.","b":"Cıvalı/alkollü termometre, dijital termometre, kızılötesi (temassız) termometre, bimetal termometre."},{"f":"Öz ısı (özgül ısı) nedir?","b":"Bir maddenin 1 gramının sıcaklığını 1°C artırmak için gereken ısı miktarıdır."},{"f":"Isı sığası nedir?","b":"Bir cismin tamamının sıcaklığını 1°C artırmak için gereken ısı miktarıdır; kütleye bağlıdır."},{"f":"Öz ısı ile ısı sığası arasındaki fark nedir?","b":"Öz ısı maddenin cinsine özgü sabit bir değerdir; ısı sığası cismin kütlesine bağlı olarak değişir."},{"f":"Denizler karalardan neden geç ısınıp geç soğur?","b":"Suyun öz ısısı topraktan çok yüksek olduğu için aynı ısıyı alıp verirken sıcaklığı daha yavaş değişir."},{"f":"Hâl değişimi nedir?","b":"Bir maddenin katı, sıvı, gaz hâlleri arasında dönüşüm geçirmesidir."},{"f":"Hâl değişimi sırasında sıcaklık ne olur?","b":"Madde ısı alıp verse de hâl değişimi tamamlanana kadar sıcaklık sabit kalır."},{"f":"Isıl denge nedir?","b":"Farklı sıcaklıktaki iki cismin temas ettiğinde ısı alışverişi sonucu aynı sıcaklığa ulaşması durumudur."},{"f":"Isının üç iletim yolu nedir?","b":"İletim (kondüksiyon), taşınım (konveksiyon) ve ışınım (radyasyon)."},{"f":"Isı iletimi (kondüksiyon) nedir?","b":"Isının madde içinde tanecikten taneciğe, doğrudan temasla aktarılmasıdır."},{"f":"Isı taşınımı (konveksiyon) nedir?","b":"Sıvı veya gazlarda ısınan bölgenin yükselip soğuk bölgenin yer değiştirmesiyle ısının taşınmasıdır."},{"f":"Isı ışınımı (radyasyon) nedir ve neden özeldir?","b":"Elektromanyetik dalgalarla ısı aktarımıdır; boşlukta da gerçekleşebilen tek ısı iletim yoludur."},{"f":"Soğuk bölgelerde duvarların kalın, pencerelerin küçük yapılmasının nedeni nedir?","b":"İletim yoluyla ısı kaybını azaltarak enerji tasarrufu sağlamaktır."},{"f":"Hissedilen sıcaklık ile gerçek sıcaklık neden farklı olabilir?","b":"Nem ve rüzgâr gibi etkenler vücuttan ısı kaybı hızını değiştirerek algılanan sıcaklığı etkiler."},{"f":"Küresel ısınmanın temel nedeni nedir?","b":"Sera gazı salımlarının artmasıyla atmosferin daha fazla ısı tutmasıdır."},{"f":"Genleşme nedir?","b":"Bir maddenin ısınınca hacminin artmasıdır; büzülme ise soğuyunca hacminin azalmasıdır."},{"f":"Su donunca hacmi nasıl değişir?","b":"Çoğu maddenin aksine su donunca genleşir, hacmi artar ve özkütlesi azalır."},{"f":"Buz suda neden yüzer?","b":"Donan suyun özkütlesi sıvı sudan daha küçük olduğu için buz suyun üzerinde yüzer."},{"f":"Isı yalıtımının aile bütçesine katkısı nedir?","b":"Isı kaybını azaltarak ısınma/soğutma masraflarını düşürür ve enerji tasarrufu sağlar."}]},{"id":"fiz-6","name":"Elektrostatik","cards":[{"f":"Elektrik yükü nedir?","b":"Maddenin, elektriksel kuvvet uygulama ve elektriksel kuvvetten etkilenme özelliğidir."},{"f":"Elektrikle yüklenmenin üç yolu nedir?","b":"Sürtünme ile yüklenme, dokunma ile yüklenme ve etki (indüksiyon) ile yüklenme."},{"f":"Sürtünme ile yüklenme nasıl gerçekleşir?","b":"İki farklı cismin birbirine sürtülmesiyle elektronların bir cisimden diğerine geçmesiyle oluşur."},{"f":"Dokunma ile yüklenme nasıl gerçekleşir?","b":"Yüklü bir cismin nötr bir cisme doğrudan temas etmesiyle yükün bir kısmının aktarılmasıyla oluşur."},{"f":"Etki (indüksiyon) ile yüklenme nasıl gerçekleşir?","b":"Yüklü bir cisim, nötr bir cisme dokunmadan yaklaşarak onun üzerinde yük dağılımı oluşturur."},{"f":"Yük korunumu ilkesi ne der?","b":"Yüklenme sırasında yük yoktan var edilmez veya yok edilmez; sadece bir cisimden diğerine aktarılır."},{"f":"Elektrikle yüklenmede hangi tanecikler hareket eder?","b":"Genellikle elektronlar hareket eder; protonlar atom çekirdeğinde sabit kalır."},{"f":"Elektroskop ne işe yarar?","b":"Bir cismin yüklü olup olmadığını ve yük cinsini belirlemeye yarayan alettir."},{"f":"İletken madde nedir?","b":"İçindeki yüklerin (elektronların) serbestçe hareket edebildiği maddedir."},{"f":"Yalıtkan madde nedir?","b":"İçindeki yüklerin serbestçe hareket edemediği maddedir."},{"f":"İletken bir cisimde verilen yük nasıl dağılır?","b":"Yükler birbirini iterek cismin dış yüzeyine yayılır."},{"f":"Yalıtkan bir cisimde verilen yük nasıl dağılır?","b":"Yükler hareket edemediği için verildiği bölgede sabit kalır."},{"f":"Faraday kafesi ne işe yarar?","b":"İçindeki alanı dış elektrik alanlardan korur; hassas cihazları ekranlamada ve yıldırımdan korunmada kullanılır."},{"f":"Topraklama nedir ve neden önemlidir?","b":"Fazla elektrik yükünün toprağa aktarılmasıdır; elektrik çarpması ve yangın riskini azaltır."},{"f":"Coulomb Kuvveti neye bağlıdır?","b":"İki yükün büyüklüklerinin çarpımına ve aralarındaki uzaklığa bağlıdır."},{"f":"Coulomb Kuvveti uzaklıkla nasıl değişir?","b":"Uzaklığın karesiyle ters orantılı olarak azalır; uzaklık iki katına çıkarsa kuvvet dörtte birine iner."},{"f":"Elektrik alan nedir?","b":"Yüklü bir cismin çevresinde başka bir yüke kuvvet uygulayabildiği bölgedir."},{"f":"Elektrik alanın yönü nasıl belirlenir?","b":"Bölgeye konan pozitif bir test yükünün hareket edeceği yön ile belirlenir."},{"f":"Aynı cins yükler birbirine nasıl etki eder?","b":"Birbirini iter."},{"f":"Farklı cins yükler birbirine nasıl etki eder?","b":"Birbirini çeker."},{"f":"Nötr bir cisim ne demektir?","b":"Eşit sayıda pozitif ve negatif yük içeren, net yükü sıfır olan cisimdir."},{"f":"Şimşek olayı elektrostatikle nasıl açıklanır?","b":"Bulutlarda biriken elektrik yükünün, yer ile bulut arasında ani boşalmasıyla oluşur."}]},{"id":"fiz-7","name":"Elektrik ve Manyetizma","cards":[{"f":"Elektrik akımı nedir?","b":"Yüklerin (iletkenlerde serbest elektronların) bir iletken boyunca düzenli hareketidir."},{"f":"Elektrik akımının birimi nedir?","b":"Amperdir (A)."},{"f":"Potansiyel fark (gerilim) nedir?","b":"İki nokta arasında birim yükü taşımak için gereken enerjidir; birimi volttur (V)."},{"f":"Direnç nedir?","b":"Bir iletkenin, üzerinden geçen elektrik akımına gösterdiği zorluktur; birimi ohm'dur (Ω)."},{"f":"Katı, sıvı, gaz ve plazmada elektrik iletimi mümkün müdür?","b":"Evet. Katılarda serbest elektronlar, sıvılarda (çözeltilerde) iyonlar, gazlarda ve plazmada iyonlar ile elektronlar yük taşır."},{"f":"Bir iletkenin direnci hangi değişkenlere bağlıdır?","b":"İletkenin uzunluğuna, kesit alanına ve yapıldığı maddenin cinsine bağlıdır."},{"f":"Ohm Yasası neyi ilişkilendirir?","b":"Bir devredeki elektrik akımı, direnç ve potansiyel fark arasındaki ilişkiyi ifade eder."},{"f":"Ampermetre devreye nasıl bağlanır?","b":"Devreye seri bağlanır ve direnci çok küçük olmalıdır ki devreyi etkilemesin."},{"f":"Voltmetre devreye nasıl bağlanır?","b":"Ölçüm yapılacak elemana paralel bağlanır ve direnci çok büyük olmalıdır."},{"f":"Üreteçlerin seri bağlanmasının amacı nedir?","b":"Devredeki toplam gerilimi (elektromotor kuvveti) artırmaktır."},{"f":"Üreteçlerin paralel bağlanmasının amacı nedir?","b":"Üreteçlerin daha uzun süre dayanmasını (tükenme süresini uzatmayı) sağlamaktır."},{"f":"İç direnç nedir?","b":"Bir üretecin kendi iç yapısından kaynaklanan ve akıma karşı gösterdiği dirençtir."},{"f":"Galvani ve Volta arasındaki görüş ayrılığı neydi?","b":"Galvani elektriğin canlı dokudan geldiğini savundu; Volta farklı metallerin temasından kaynaklandığını gösterip ilk pili yaptı."},{"f":"Elektriksel güç nedir?","b":"Bir devre elemanının birim zamanda harcadığı veya ürettiği elektrik enerjisi miktarıdır."},{"f":"Bir lambanın parlaklığı neye bağlıdır?","b":"Lambanın harcadığı elektriksel güce bağlıdır; güç arttıkça parlaklık artar."},{"f":"Elektrik çarpmasına karşı hangi güvenlik önlemleri alınır?","b":"Islak elle prize dokunmamak, topraklama ve sigorta kullanmak, hasarlı kabloları kullanmamak."},{"f":"Mıknatısların aynı kutupları ve farklı kutupları nasıl etkileşir?","b":"Aynı kutuplar (K-K veya G-G) birbirini iter; farklı kutuplar (K-G) birbirini çeker."},{"f":"Manyetik alan çizgileri neyi gösterir?","b":"Mıknatısın çevresindeki manyetik alanın yönünü ve şiddetini gösterir; kuzeyden çıkıp güneye girer."},{"f":"Sağ el kuralı ne işe yarar?","b":"Akım taşıyan bir telin çevresinde oluşan manyetik alanın yönünü bulmaya yarar."},{"f":"Elektromıknatıs nedir?","b":"Üzerinden akım geçen bir tel sarımının oluşturduğu, akım kesilince manyetik özelliğini kaybeden mıknatıstır."},{"f":"Dünya'nın manyetik alanı pusulayı nasıl etkiler?","b":"Pusula iğnesi, Dünya'nın manyetik alanına göre yönelerek kuzey-güney yönünü gösterir."},{"f":"Hangi canlılar Dünya'nın manyetik alanından yön bulmak için yararlanır?","b":"Arılar, göçmen kuşlar ve bazı büyükbaş hayvanlar."}]},{"id":"fiz-8","name":"Basınç ve Kaldırma Kuvveti","cards":[{"f":"Basınç nedir?","b":"Birim yüzey alanına etki eden dik kuvvettir."},{"f":"Basıncın birimi nedir?","b":"Pascal'dır (Pa)."},{"f":"Katı basıncı hangi değişkenlere bağlıdır?","b":"Uygulanan kuvvete ve temas yüzey alanına bağlıdır."},{"f":"Basınç kaynama sıcaklığını nasıl etkiler?","b":"Basınç arttıkça kaynama sıcaklığı yükselir (düdüklü tencere); basınç azalınca düşer."},{"f":"Torricelli deneyi neyi gösterir?","b":"Cıva sütunu yardımıyla atmosfer basıncının varlığını ve büyüklüğünü gösteren deneydir."},{"f":"Torricelli deneyi kılcallıktan nasıl ayrılır?","b":"Torricelli atmosfer basıncını ölçer; kılcallık ise adezyon-kohezyon dengesiyle ilgili ayrı bir olaydır."},{"f":"Barometre ne ölçer?","b":"Atmosfer (hava) basıncını ölçer."},{"f":"Altimetre ne işe yarar?","b":"Hava basıncından yararlanarak bulunulan yüksekliği belirler."},{"f":"Manometre ne ölçer?","b":"Kapalı bir kaptaki gazın basıncını ölçer."},{"f":"Batimetre ne ölçer?","b":"Su derinliğini ölçer."},{"f":"Pascal Prensibi ne der?","b":"Kapalı bir kaptaki durgun sıvıya uygulanan basınç, sıvının her noktasına eşit olarak iletilir."},{"f":"Pascal Prensibi hangi araçlarda uygulanır?","b":"Hidrolik fren ve hidrolik kriko gibi sistemlerde uygulanır."},{"f":"Bernoulli İlkesi ne der?","b":"Bir akışkanın hızı arttıkça, o bölgedeki basıncı azalır."},{"f":"Bernoulli İlkesi'ne bir örnek veriniz.","b":"Rüzgârlı havada evlerin çatısının uçması; çatı üstündeki hızlı hava akımı basıncı düşürür."},{"f":"Uçaklar Bernoulli İlkesi'yle nasıl uçar?","b":"Kanat üstündeki hava alttakinden hızlı aktığı için üstte basınç düşer ve kaldırma kuvveti oluşur."},{"f":"Tansiyon neyi ölçer?","b":"Kan damarlarındaki kan basıncını ölçer."},{"f":"Akışkan basıncına karşı alınması gereken bir güvenlik önlemi nedir?","b":"Yüksek süratle hareket eden araçlara yakın durmamak; oluşan basınç farkı çekme etkisi yaratabilir."},{"f":"Archimedes İlkesi ne der?","b":"Bir akışkana batırılan cisme, cismin taşırdığı akışkanın ağırlığı kadar yukarı yönlü kaldırma kuvveti etki eder."},{"f":"Kaldırma kuvveti neye bağlıdır?","b":"Cismin taşırdığı akışkanın ağırlığına, dolayısıyla akışkanın özkütlesine ve taşırılan hacme bağlıdır."},{"f":"Bir cisim ne zaman yüzer?","b":"Özkütlesi sıvının özkütlesinden küçükse yüzer; yüzerken kaldırma kuvveti ağırlığına eşittir."},{"f":"Bir cisim ne zaman batar?","b":"Özkütlesi sıvının özkütlesinden büyükse batar; kaldırma kuvveti ağırlığından küçük kalır."},{"f":"Bir cisim ne zaman askıda kalır?","b":"Özkütlesi sıvının özkütlesine eşitse tamamen batmış hâlde dengede (askıda) kalır; kaldırma kuvveti ağırlığa eşittir."},{"f":"Basıncın günlük hayattaki bir etkisi nedir?","b":"Yüksek rakımda hava basıncının düşmesi nedeniyle suyun kaynama sıcaklığı düşer."}]},{"id":"fiz-9","name":"Dalgalar","cards":[{"f":"Dalga nedir?","b":"Bir titreşimin, madde taşınmadan ortam içinde enerji taşıyarak ilerlemesidir."},{"f":"Titreşim nedir?","b":"Bir cismin denge konumu etrafında tekrarlanan hareketidir."},{"f":"Dalga boyu nedir?","b":"Bir dalganın birbirini izleyen iki benzer noktası (örneğin iki tepe) arasındaki uzaklıktır."},{"f":"Periyot nedir?","b":"Bir tam titreşimin tamamlanması için geçen süredir."},{"f":"Frekans nedir?","b":"Birim zamandaki titreşim sayısıdır."},{"f":"Periyot ile frekans arasındaki ilişki nedir?","b":"Birbirinin çarpmaya göre tersidir; biri artarken diğeri azalır."},{"f":"Genlik nedir?","b":"Titreşen bir noktanın denge konumundan yaptığı en büyük uzaklaşma miktarıdır."},{"f":"Dalganın ilerleme hızı neye bağlıdır?","b":"İçinde ilerlediği ortamın özelliklerine bağlıdır; frekansa bağlı değildir."},{"f":"Dalganın frekansı neye bağlıdır?","b":"Dalgayı üreten kaynağa bağlıdır; ortam değişse de frekans değişmez."},{"f":"Dalgalar madde taşır mı?","b":"Hayır, dalgalar madde taşımaz; yalnızca enerji taşır."},{"f":"Dalgalar ortam ihtiyacına göre nasıl sınıflandırılır?","b":"Mekanik dalgalar (yayılmak için ortama ihtiyaç duyar) ve elektromanyetik dalgalar (boşlukta da yayılabilir) olarak sınıflandırılır."},{"f":"Enine dalga ile boyuna dalga arasındaki fark nedir?","b":"Enine dalgada titreşim yönü ilerleme yönüne diktir (ip, su yüzeyi); boyuna dalgada titreşim ilerleme yönüyle aynı doğrultudadır (ses, yay)."},{"f":"Atma nedir?","b":"Bir ortamda tek seferlik oluşturulan, tekrarlanmayan dalga bozulmasıdır."},{"f":"Periyodik dalga nedir?","b":"Kaynağın sürekli ve düzenli titreşimiyle oluşan, tekrarlanan dalgadır."},{"f":"Bir atma sabit uçtan yansırken nasıl davranır?","b":"Ters dönerek (fazı 180° kayarak) yansır."},{"f":"Bir atma serbest uçtan yansırken nasıl davranır?","b":"Aynı yönde (fazı korunarak) yansır."},{"f":"Dalga tepesi ve dalga çukuru nedir?","b":"Dalga tepesi en yüksek nokta, dalga çukuru en alçak noktadır."},{"f":"Su dalgaları hangi biçimlerde incelenir?","b":"Doğrusal su dalgaları ve dairesel su dalgaları olarak incelenir."},{"f":"Stroboskop ne işe yarar?","b":"Hareketi durmuş gibi göstererek su dalgalarının dalga boyunu ölçmede kullanılan bir araçtır."},{"f":"Ses yüksekliği ile ses şiddeti arasındaki fark nedir?","b":"Yükseklik frekansla, şiddet ise dalganın taşıdığı enerji (genlik) ile ilgilidir."},{"f":"Tını nedir?","b":"Aynı notayı çalan farklı enstrümanları birbirinden ayıran ses özelliğidir."},{"f":"Rezonans nedir?","b":"Bir sistemin kendi doğal frekansına eşit bir dış uyaranla titreştirildiğinde genliğinin aşırı artmasıdır."},{"f":"Yankı nasıl oluşur?","b":"Sesin bir yüzeyden yansıyıp, kulağın ayırt edebileceği bir gecikmeyle tekrar duyulmasıyla oluşur."},{"f":"Farabi'nin ses bilimine katkısı nedir?","b":"Ses dalgalarının yayılması ve müzik teorisi üzerine önemli çalışmalar yapmıştır."},{"f":"Deprem büyüklüğü ile şiddeti arasındaki fark nedir?","b":"Büyüklük depremin kaynağındaki enerjiyi tek bir sayıyla ifade eder; şiddet bölgeye göre değişen hasar etkisidir."},{"f":"Ses dalgaları hangi alanlarda kullanılır?","b":"Tıp (ultrason), denizcilik (sonar), sanat (müzik) ve coğrafya (yer araştırmaları) alanlarında kullanılır."}]},{"id":"fiz-10","name":"Optik","cards":[{"f":"Aydınlanma şiddeti nedir?","b":"Bir yüzeyin birim alanına düşen ışık miktarının göstergesidir."},{"f":"Işık şiddeti ve ışık akısı ile aydınlanma şiddeti arasında nasıl bir ilişki vardır?","b":"Kaynağın ışık şiddeti ve yaydığı ışık akısı arttıkça, aydınlatılan yüzeydeki aydınlanma şiddeti de artar."},{"f":"Gölge nedir?","b":"Işık kaynağının ışınlarının hiç ulaşamadığı, tam karanlık bölgedir."},{"f":"Yarı gölge nedir?","b":"Işık kaynağının ışınlarının bir kısmının ulaştığı, kısmen aydınlık bölgedir."},{"f":"Saydam madde nedir?","b":"Işığı büyük ölçüde geçiren, arkasındaki cisimlerin net görülmesini sağlayan maddedir."},{"f":"Yarı saydam madde nedir?","b":"Işığın bir kısmını geçiren, arkasındaki cisimlerin bulanık görülmesine yol açan maddedir."},{"f":"Saydam olmayan (opak) madde nedir?","b":"Işığı hiç geçirmeyen maddedir."},{"f":"Yansıma kanunları nedir?","b":"Gelme açısı yansıma açısına eşittir; gelen ışın, yansıyan ışın ve normal aynı düzlemdedir."},{"f":"Düzgün yansıma nedir?","b":"Pürüzsüz yüzeylerde paralel gelen ışınların paralel olarak yansımasıdır."},{"f":"Dağınık yansıma nedir?","b":"Pürüzlü yüzeylerde ışınların farklı yönlere dağılarak yansımasıdır."},{"f":"Düzlem aynada oluşan görüntünün özellikleri nelerdir?","b":"Cisimle aynı büyüklükte, sanaldır (perdeye düşürülemez) ve sağ-sol simetriktir."},{"f":"Çukur ayna günlük hayatta nerede kullanılır?","b":"Makyaj/tıraş aynasında ve araç farlarının reflektöründe kullanılır."},{"f":"Tümsek ayna günlük hayatta nerede kullanılır?","b":"Araç dikiz aynasında ve market güvenlik aynasında; geniş görüş açısı sağlar."},{"f":"Küresel aynada odak noktası nedir?","b":"Aynaya paralel gelen ışınların yansıdıktan sonra kesiştiği (veya kesişiyormuş gibi göründüğü) noktadır."},{"f":"Kırılma nedir?","b":"Işığın kırılma indisi farklı iki saydam ortam arasında geçerken doğrultusunun değişmesidir."},{"f":"Kırılma indisi nedir?","b":"Işığın boşluktaki hızının, ortamdaki hızına oranıdır; ortamın ışığı ne kadar yavaşlattığını gösterir."},{"f":"Kırılma indisi büyük olan bir ortamda ışık nasıl davranır?","b":"Işık bu ortamda daha yavaş ilerler."},{"f":"Tam yansıma hangi koşulda gerçekleşir?","b":"Işık, kırılma indisi büyük bir ortamdan küçük bir ortama, sınır açısından büyük açıyla geldiğinde tüm ışık yansır."},{"f":"Sınır açısı nedir?","b":"Kırılan ışının 90° açıyla yüzeye paralel çıktığı, tam yansımanın başladığı gelme açısıdır."},{"f":"Fiber optik teknolojisi hangi ilkeyle çalışır?","b":"Tam yansıma ilkesiyle çalışır; ışık kabloda sürekli yansıyarak ilerler."},{"f":"Serap olayı nasıl açıklanır?","b":"Sıcak havanın farklı yoğunluk katmanları oluşturmasıyla ışığın tam yansımaya uğramasıyla oluşan görsel yanılsamadır."},{"f":"Görünür uzaklık nedir?","b":"Farklı bir ortamda bulunan bir cismin, kırılma nedeniyle gerçek konumundan farklı bir yerde görünmesidir."},{"f":"İnce kenarlı (yakınsak) mercek nedir?","b":"Kendisine paralel gelen ışınları bir noktada toplayan, ortası kenarlarından kalın mercektir."},{"f":"Kalın kenarlı (ıraksak) mercek nedir?","b":"Kendisine paralel gelen ışınları birbirinden uzaklaştıran, ortası kenarlarından ince mercektir."},{"f":"Işık prizması ne işe yarar?","b":"Beyaz ışığı, renklerin farklı kırılma indisine sahip olması nedeniyle bileşen renklerine ayırır."},{"f":"Işıkta ana renkler ile boyada ana renkler nasıl farklıdır?","b":"Işıkta ana renkler kırmızı, yeşil, mavidir; boyada ana renkler camgöbeği, magenta, sarıdır."},{"f":"Bir cisim neden belirli bir renkte görünür?","b":"Üzerine düşen ışıktan o renk dışındaki renkleri soğurur, yalnızca kendi rengini yansıtır."},{"f":"Saf sarı ışık ile karışım sarı arasındaki fark nedir?","b":"Saf sarı tek dalga boyundan oluşurken, karışım sarı kırmızı ve yeşil ışığın birleşiminden oluşur; göze aynı görünür."}]}]},{"subject":"Kimya","units":[{"id":"kim-1","name":"Kimya Bilimi","cards":[{"f":"Simya ile kimya bilimi arasındaki temel fark nedir?","b":"Simya mistik inanışlara dayanır ve altın elde etmeyi amaçlar; kimya bilimsel yönteme dayanan sistematik bir bilim dalıdır."},{"f":"Kimyanın bilim olma sürecine katkı sağlayan bilim insanlarından ikisini say.","b":"Örnekler: Empedokles, Demokritos, Aristo, Câbir bin Hayyan, Ebubekir er-Râzî, Robert Boyle, Antoine Lavoisier."},{"f":"Câbir bin Hayyan hangi uygarlığın kimya bilimine katkı sağlayan bilim insanıdır?","b":"İslam uygarlığı; simyadan kimyaya geçiş sürecine katkı sağlamıştır."},{"f":"Ebubekir er-Razi kimya tarihinde neyle anılır?","b":"Simyadan kimyaya geçiş sürecine katkı sağlayan İslam alimlerinden biridir."},{"f":"Biyokimya neyi inceler?","b":"Canlı organizmalardaki kimyasal olayları ve yapıları inceleyen kimya dalı."},{"f":"Analitik kimya neyi inceler?","b":"Maddelerin bileşimini ve içerdiği maddelerin miktarını belirlemeyi inceleyen kimya dalı."},{"f":"Organik kimya neyi inceler?","b":"Karbon içeren bileşikleri inceleyen kimya dalı."},{"f":"Anorganik kimya neyi inceler?","b":"Karbon içermeyen (genelde metal/mineral kökenli) bileşikleri inceleyen kimya dalı."},{"f":"Polimer kimyası neyi inceler?","b":"Küçük birimlerin (monomer) tekrarıyla oluşan büyük moleküllü maddeleri (polimerleri) inceleyen kimya dalı."},{"f":"Element nedir?","b":"Aynı cins atomlardan oluşan, kimyasal yolla daha basit maddelere ayrıştırılamayan saf madde."},{"f":"Bileşik nedir?","b":"Farklı elementlerin belirli oranlarda kimyasal yollarla birleşmesiyle oluşan, kendine özgü özellikleri olan saf madde."},{"f":"H₂O bileşiğinin yaygın adı nedir?","b":"Su."},{"f":"NaCl bileşiğinin yaygın adı nedir?","b":"Sofra tuzu (sodyum klorür)."},{"f":"NaHCO₃ bileşiğinin yaygın adı nedir?","b":"Kabartma tozu / karbonat (sodyum bikarbonat)."},{"f":"CH₃COOH bileşiğinin yaygın adı nedir?","b":"Asetik asit; sulu çözeltisi sirke olarak bilinir."},{"f":"Ca(OH)₂ bileşiğinin yaygın adı nedir?","b":"Sönmüş kireç (kalsiyum hidroksit)."},{"f":"NaOH bileşiğinin yaygın adı nedir?","b":"Kostik (sodyum hidroksit)."},{"f":"CaO bileşiğinin yaygın adı nedir?","b":"Sönmemiş kireç (kalsiyum oksit)."},{"f":"H₂SO₄ bileşiğinin yaygın adı nedir?","b":"Zaç yağı (sülfürik asit)."},{"f":"HNO₃ bileşiğinin yaygın adı nedir?","b":"Kezzap (nitrik asit)."},{"f":"Yanıcı madde uyarı işareti neyi gösterir?","b":"Kolayca alev alabilen maddeleri; ateş ve kıvılcımdan uzak tutulmalıdır."},{"f":"Yakıcı (oksitleyici) madde uyarı işareti neyi gösterir?","b":"Yanmayı başlatan ya da şiddetlendiren (oksijen veren) maddeleri; yanıcı maddelerden uzak tutulmalıdır."},{"f":"Korozif (aşındırıcı) madde uyarı işareti neyi gösterir?","b":"Metalleri ve canlı dokuları aşındırabilen maddeleri; eldiven ve gözlük gerektirir."},{"f":"Patlayıcı madde uyarı işareti neyi gösterir?","b":"Ani ve şiddetli tepkimeyle patlayabilen maddeleri."},{"f":"Tahriş edici madde uyarı işareti neyi gösterir?","b":"Deri, göz veya solunum yollarında geçici rahatsızlık/kızarıklık yapabilen maddeleri."},{"f":"Zehirli (toksik) madde uyarı işareti neyi gösterir?","b":"Solunduğunda, yutulduğunda veya cilde temas ettiğinde sağlığa ciddi zarar veren maddeleri."},{"f":"Radyoaktif madde uyarı işareti neyi gösterir?","b":"İyonlaştırıcı radyasyon yayan, canlılara zarar verebilen maddeleri."},{"f":"Çevreye zararlı madde uyarı işareti neyi gösterir?","b":"Doğaya, su kaynaklarına ve canlılara zarar verebilecek maddeleri."},{"f":"Beherglas hangi amaçla kullanılır?","b":"Sıvıları karıştırmak, ısıtmak veya yaklaşık hacim ölçmek için kullanılan geniş ağızlı laboratuvar kabı."},{"f":"Balon joje ne için kullanılır?","b":"Belirli hacimde çözeltiyi hassas biçimde hazırlamak için kullanılan, tek çizgili ölçekli cam kap."},{"f":"Ayırma hunisi laboratuvarda ne için kullanılır?","b":"Birbiri içinde çözünmeyen sıvıları yoğunluk farkından yararlanarak ayırmak için kullanılır."},{"f":"Na, K, Ca, Mg, H₂O maddeleri insan sağlığı için neden önemlidir?","b":"Vücut fonksiyonları için gerekli temel element ve bileşiklerdir (elektrolit dengesi, kemik yapısı vb.)."},{"f":"Hg ve Pb gibi ağır metaller insan sağlığı açısından nasıl bir risk taşır?","b":"Vücutta birikerek sinir sistemi ve organlara zarar verebilen zehirli ağır metallerdir."}]},{"id":"kim-2","name":"Atom ve Periyodik Sistem","cards":[{"f":"Dalton atom modelinin özelliği nedir?","b":"Atomun bölünemez, içi dolu ve sert bir küre olduğunu öne sürer."},{"f":"Thomson atom modelinin özelliği nedir?","b":"Üzümlü kek modeli: pozitif yüklü küre içine gömülü elektronlar."},{"f":"Rutherford atom modelinin özelliği nedir?","b":"Atomun pozitif yükünün küçük bir çekirdekte toplandığını, çevresinde elektronların dolandığını öne sürer (gezegen modeli)."},{"f":"Bohr atom modelinin özelliği nedir?","b":"Elektronların belirli enerji seviyelerinde (katmanlarda) dolandığını; atomun ışın soğurma/yayma davranışını açıklar."},{"f":"Modern atom teorisi (bulut modeli) neyi öne sürer?","b":"Elektronların çekirdek çevresinde kesin bir yörüngede değil, bulunma olasılığı yüksek bölgelerde (elektron bulutu) bulunduğunu."},{"f":"Emisyon (yayma) nedir?","b":"Atomun yüksek enerji seviyesinden düşük seviyeye geçerken ışın (enerji) yayması."},{"f":"Absorbsiyon (soğurma) nedir?","b":"Atomun düşük enerji seviyesinden yüksek seviyeye geçerken ışın (enerji) soğurması."},{"f":"Protonun yükü ve atomdaki yeri nedir?","b":"+1 yüklü, çekirdekte bulunur."},{"f":"Nötronun yükü ve atomdaki yeri nedir?","b":"Yüksüzdür, çekirdekte bulunur."},{"f":"Elektronun yükü ve atomdaki yeri nedir?","b":"-1 yüklü, çekirdek dışında (katmanlarda) bulunur."},{"f":"Atom numarası neyi ifade eder?","b":"Bir atomun çekirdeğindeki proton sayısını."},{"f":"Kütle numarası neyi ifade eder?","b":"Bir atomun çekirdeğindeki proton ve nötron sayılarının toplamını."},{"f":"İzotop atomlar nedir?","b":"Proton sayısı aynı, nötron sayısı (dolayısıyla kütle numarası) farklı olan atomlar."},{"f":"İzoton atomlar nedir?","b":"Nötron sayısı aynı, proton sayısı farklı olan atomlar."},{"f":"İzobar atomlar nedir?","b":"Kütle numarası aynı, proton sayısı farklı olan atomlar."},{"f":"İzoelektronik tanecikler nedir?","b":"Elektron sayıları birbirine eşit olan atom veya iyonlar."},{"f":"Mendeleyev'in periyodik sisteme katkısı nedir?","b":"Elementleri artan atom kütlesine ve benzer özelliklerine göre bir tabloda düzenlemiştir."},{"f":"Moseley'in periyodik sisteme katkısı nedir?","b":"Elementleri atom numarasına (proton sayısına) göre sıralayarak periyodik sistemi geliştirmiştir."},{"f":"Periyodik sistemde elementler nasıl sınıflandırılır?","b":"Metal, ametal, yarı metal (metaloid) ve asal (soy) gazlar olarak sınıflandırılır."},{"f":"Metale örnek ver.","b":"Demir, sodyum, bakır, alüminyum."},{"f":"Ametale örnek ver.","b":"Oksijen, azot, klor, kükürt."},{"f":"Yarı metale (metaloide) örnek ver.","b":"Bor, silisyum, germanyum."},{"f":"Asal (soy) gaza örnek ver.","b":"Helyum, neon, argon."},{"f":"Aynı periyotta soldan sağa gidildikçe atom yarıçapı nasıl değişir?","b":"Azalır."},{"f":"Aynı grupta yukarıdan aşağıya gidildikçe atom yarıçapı nasıl değişir?","b":"Artar."},{"f":"İyonlaşma enerjisi nedir?","b":"Bir atomdan bir elektronu koparmak için gereken minimum enerji."},{"f":"Elektronegatiflik nedir?","b":"Bir atomun bağ elektronlarını kendine çekme gücü."},{"f":"Elektron ilgisi nedir?","b":"Bir atomun elektron alarak negatif iyon oluştururken açığa çıkan/soğurulan enerji eğilimi."},{"f":"Hidrojen elementinin simgesi nedir?","b":"H (atom numarası 1)."},{"f":"Helyum elementinin simgesi nedir?","b":"He (atom numarası 2)."},{"f":"Lityum elementinin simgesi nedir?","b":"Li (atom numarası 3)."},{"f":"Berilyum elementinin simgesi nedir?","b":"Be (atom numarası 4)."},{"f":"Bor elementinin simgesi nedir?","b":"B (atom numarası 5)."},{"f":"Karbon elementinin simgesi nedir?","b":"C (atom numarası 6)."},{"f":"Azot elementinin simgesi nedir?","b":"N (atom numarası 7). Na (sodyum) ile karıştırılmamalı."},{"f":"Oksijen elementinin simgesi nedir?","b":"O (atom numarası 8)."},{"f":"Flor elementinin simgesi nedir?","b":"F (atom numarası 9)."},{"f":"Neon elementinin simgesi nedir?","b":"Ne (atom numarası 10)."},{"f":"Sodyum elementinin simgesi nedir?","b":"Na (atom numarası 11), Latince natrium'dan gelir. N (azot) ile karıştırılmamalı."},{"f":"Magnezyum elementinin simgesi nedir?","b":"Mg (atom numarası 12)."},{"f":"Alüminyum elementinin simgesi nedir?","b":"Al (atom numarası 13)."},{"f":"Silisyum elementinin simgesi nedir?","b":"Si (atom numarası 14)."},{"f":"Fosfor elementinin simgesi nedir?","b":"P (atom numarası 15)."},{"f":"Kükürt elementinin simgesi nedir?","b":"S (atom numarası 16), Latince sulfur'dan gelir."},{"f":"Klor elementinin simgesi nedir?","b":"Cl (atom numarası 17)."},{"f":"Argon elementinin simgesi nedir?","b":"Ar (atom numarası 18)."},{"f":"Potasyum elementinin simgesi nedir?","b":"K (atom numarası 19), Latince kalium'dan gelir. Ca (kalsiyum) ile karıştırılmamalı."},{"f":"Kalsiyum elementinin simgesi nedir?","b":"Ca (atom numarası 20). K (potasyum) ile karıştırılmamalı."},{"f":"Krom elementinin simgesi nedir?","b":"Cr."},{"f":"Mangan elementinin simgesi nedir?","b":"Mn."},{"f":"Demir elementinin simgesi nedir?","b":"Fe, Latince ferrum'dan gelir."},{"f":"Kobalt elementinin simgesi nedir?","b":"Co."},{"f":"Nikel elementinin simgesi nedir?","b":"Ni."},{"f":"Bakır elementinin simgesi nedir?","b":"Cu, Latince cuprum'dan gelir. Ca (kalsiyum) ile karıştırılmamalı."},{"f":"Çinko elementinin simgesi nedir?","b":"Zn."},{"f":"Brom elementinin simgesi nedir?","b":"Br."},{"f":"Gümüş elementinin simgesi nedir?","b":"Ag, Latince argentum'dan gelir. Au (altın) ile karıştırılmamalı."},{"f":"Kalay elementinin simgesi nedir?","b":"Sn, Latince stannum'dan gelir."},{"f":"İyot elementinin simgesi nedir?","b":"I."},{"f":"Baryum elementinin simgesi nedir?","b":"Ba."},{"f":"Platin elementinin simgesi nedir?","b":"Pt."},{"f":"Altın elementinin simgesi nedir?","b":"Au, Latince aurum'dan gelir. Ag (gümüş) ile karıştırılmamalı."},{"f":"Cıva elementinin simgesi nedir?","b":"Hg, Latince hydrargyrum'dan gelir."},{"f":"Kurşun elementinin simgesi nedir?","b":"Pb, Latince plumbum'dan gelir."}]},{"id":"kim-3","name":"Kimyasal Türler Arası Etkileşimler","cards":[{"f":"Kimyasal tür nedir?","b":"Atom, iyon veya molekül gibi kimyasal etkileşimlerde yer alan temel yapı taşları."},{"f":"Kimyasal türler arası etkileşimler nasıl iki ana gruba ayrılır?","b":"Güçlü etkileşimler (atomlar arası, kimyasal bağlar) ve zayıf etkileşimler (moleküller arası)."},{"f":"Güçlü etkileşimlere örnek olarak hangi bağlar verilir?","b":"İyonik bağ, kovalent bağ, metalik bağ."},{"f":"Zayıf etkileşimlere örnek olarak neler verilir?","b":"Hidrojen bağı ve van der Waals kuvvetleri."},{"f":"İyonik bağ nasıl oluşur?","b":"Metal atomunun elektron vermesi, ametal atomunun elektron almasıyla oluşan zıt yüklü iyonlar arasındaki çekimle."},{"f":"Kovalent bağ nasıl oluşur?","b":"Ametal atomlarının bir veya daha fazla ortak elektron çifti paylaşmasıyla oluşur."},{"f":"Apolar kovalent bağ ne zaman oluşur?","b":"Aynı cins atomlar veya elektronegatiflik farkı çok küçük atomlar arasında (örn. H₂, Cl₂, O₂, N₂)."},{"f":"Polar kovalent bağ ne zaman oluşur?","b":"Farklı elektronegatifliğe sahip atomlar arasında; elektronlar bir atoma daha yakın paylaşılır (örn. HCl, H₂O)."},{"f":"Metalik bağ nasıl açıklanır?","b":"Elektron denizi modeliyle: metal katyonlarının serbest dolaşan elektronlar denizi içinde bir arada tutulmasıyla."},{"f":"NH₄⁺ iyonunun adı nedir?","b":"Amonyum iyonu."},{"f":"OH⁻ iyonunun adı nedir?","b":"Hidroksit iyonu."},{"f":"NO₃⁻ iyonunun adı nedir?","b":"Nitrat iyonu."},{"f":"SO₄²⁻ iyonunun adı nedir?","b":"Sülfat iyonu."},{"f":"CO₃²⁻ iyonunun adı nedir?","b":"Karbonat iyonu."},{"f":"PO₄³⁻ iyonunun adı nedir?","b":"Fosfat iyonu."},{"f":"CN⁻ iyonunun adı nedir?","b":"Siyanür iyonu."},{"f":"CH₃COO⁻ iyonunun adı nedir?","b":"Asetat iyonu."},{"f":"Değişken değerlikli metallere hangi örnekler verilir?","b":"Bakır (Cu), demir (Fe), civa (Hg), kalay (Sn), kurşun (Pb)."},{"f":"H₂O bileşiğinin sistematik adı nedir?","b":"Dihidrojen monoksit (yaygın adı su)."},{"f":"HCl bileşiğinin sistematik adı nedir?","b":"Hidrojen klorür."},{"f":"NH₃ bileşiğinin sistematik adı nedir?","b":"Azot trihidrür (yaygın adı amonyak)."},{"f":"Zayıf ve güçlü etkileşimler hangi esasa göre ayrılır?","b":"Bağ enerjisi büyüklüğüne göre; güçlü etkileşimler çok daha yüksek bağ enerjisine sahiptir."},{"f":"Van der Waals kuvvetleri şemsiye terimi hangi etkileşimleri kapsar?","b":"Dipol-dipol, iyon-dipol, dipol-indüklenmiş dipol, iyon-indüklenmiş dipol ve London kuvvetleri."},{"f":"Van der Waals kuvvetleri arasında en zayıfı hangisidir?","b":"London (dağılma) kuvvetleri."},{"f":"İyon-dipol, dipol-dipol ve London kuvvetleri arasında en güçlüsü hangisidir?","b":"İyon-dipol etkileşimi."},{"f":"Hidrojen bağı hangi atomlar arasında oluşur?","b":"H atomu ile F, O veya N gibi küçük ve çok elektronegatif bir atom arasında."},{"f":"Hidrojen bağı ile van der Waals kuvvetlerinin ilişkisi nasıldır?","b":"Hidrojen bağı, van der Waals kuvvetlerinden (dipol-dipol, London vb.) genellikle daha güçlü, zayıf etkileşimlerin en kuvvetlisidir."},{"f":"Aziz Sancar bu ünitede hangi konudaki çalışmasıyla anılır?","b":"DNA'nın onarımıyla ilgili Nobel ödüllü çalışması; hidrojen bağı konusuyla ilişkilendirilir."},{"f":"Tuz (NaCl) katısında tanecikleri bir arada tutan etkileşim nedir?","b":"İyonik bağ."},{"f":"Elmas katısında tanecikleri bir arada tutan etkileşim nedir?","b":"Kovalent bağ (kovalent ağ katı)."},{"f":"Çinko katısında tanecikleri bir arada tutan etkileşim nedir?","b":"Metalik bağ."},{"f":"Katı iyotta tanecikleri bir arada tutan etkileşim nedir?","b":"Zayıf etkileşimler (van der Waals/London kuvvetleri); iyot moleküler bir katıdır."}]},{"id":"kim-4","name":"Maddenin Hâlleri","cards":[{"f":"Erime nedir?","b":"Katı halden sıvı hale geçiş."},{"f":"Donma nedir?","b":"Sıvı halden katı hale geçiş."},{"f":"Buharlaşma nedir?","b":"Sıvı halden gaz hale geçiş."},{"f":"Yoğuşma nedir?","b":"Gaz halden sıvı hale geçiş."},{"f":"Süblimleşme nedir?","b":"Katı halden doğrudan gaz hale geçiş."},{"f":"Kırağılaşma (geri süblimleşme) nedir?","b":"Gaz halden doğrudan katı hale geçiş."},{"f":"Plazma nedir?","b":"Çok yüksek sıcaklıkta gazın iyonlaşmasıyla oluşan, maddenin dördüncü hâli."},{"f":"Viskozite nedir?","b":"Bir sıvının akmaya karşı gösterdiği direnç."},{"f":"Sıcaklık arttıkça sıvıların viskozitesi genellikle nasıl değişir?","b":"Azalır; sıvı daha akışkan hale gelir."},{"f":"Buhar basıncı nedir?","b":"Kapalı bir kapta sıvı ile dengede bulunan buharın yaptığı basınç."},{"f":"Kaynama neye bağlıdır?","b":"Dış basınca; sıvının buhar basıncı dış basınca eşitlendiğinde kaynama başlar."},{"f":"Nem nedir?","b":"Atmosferdeki su buharının varlığını ifade eden kavram."},{"f":"Katıların bağ türü tanıtımında kullanılan dört örnek katı hangileridir?","b":"Tuz (iyonik), iyot (moleküler), elmas (kovalent ağ), çinko (metalik)."},{"f":"Katıların tanecikleri arasındaki bağ gücü hangi özellikle ilişkilendirilir?","b":"Erime noktası ve sertlik gibi fiziksel özelliklerle."},{"f":"Gaz basıncı hangi birimlerle ifade edilir?","b":"atm (atmosfer) ve mmHg (cıva milimetresi)."},{"f":"Gaz hacmi hangi birimle ifade edilir?","b":"Litre (L)."},{"f":"Gaz sıcaklığı hangi birimlerle ifade edilir?","b":"Celsius (°C) ve Kelvin (K)."},{"f":"Gaz miktarı hangi birimle ifade edilir?","b":"Mol."},{"f":"LPG nedir?","b":"Sıvılaştırılmış petrol gazı."},{"f":"LNG nedir?","b":"Sıvılaştırılmış doğal gaz."},{"f":"Mutlak sıcaklık nedir?","b":"Kelvin cinsinden ölçülen, en düşük değeri mutlak sıfır (0 K) olan sıcaklık ölçeği."},{"f":"Bağıl nem neyi ifade eder?","b":"Havadaki mevcut su buharı miktarının, o sıcaklıkta taşınabilecek maksimum miktara oranını."},{"f":"Genleşme nedir?","b":"Maddenin sıcaklık artışıyla hacminin büyümesi."},{"f":"Akışkanlık hangi madde hâllerinin ortak özelliğidir?","b":"Sıvılar ve gazlar; şekil değiştirip akabilme özelliğidir."}]},{"id":"kim-5","name":"Doğa ve Kimya","cards":[{"f":"Sert su nedir?","b":"Kalsiyum ve magnezyum iyonlarını fazla miktarda içeren su."},{"f":"Yumuşak su nedir?","b":"Kalsiyum ve magnezyum iyonları az olan, sabunla kolay köpüren su."},{"f":"Sert suyun günlük hayattaki olumsuz etkisi nedir?","b":"Sabunla iyi köpürmez, musluk ve borularda kireçlenmeye yol açar."},{"f":"Su tasarrufunun önemi nedir?","b":"Sınırlı su kaynaklarının gelecek nesillere aktarılması ve ekosistemin korunması için gereklidir."},{"f":"Başlıca hava kirleticileri nelerdir?","b":"Azot oksitler, karbon dioksit ve kükürt oksitleri."},{"f":"Başlıca su ve toprak kirleticileri nelerdir?","b":"Plastikler, deterjanlar, organik sıvılar, ağır metaller, piller, endüstriyel atıklar."},{"f":"Sera etkisi nedir?","b":"Atmosferdeki bazı gazların güneşten gelen ısıyı tutarak dünyanın ısınmasına yol açması."},{"f":"Sera etkisine en çok katkı yapan gazlardan biri hangisidir?","b":"Karbon dioksit (CO₂)."},{"f":"Küresel ısınma nedir?","b":"Sera etkisinin artmasıyla dünya ortalama sıcaklığının zamanla yükselmesi."},{"f":"Asit yağmurlarına yol açan başlıca hava kirleticiler hangileridir?","b":"Kükürt oksitler ve azot oksitler."},{"f":"Piller çevreye nasıl zarar verir?","b":"İçerdikleri ağır metaller (kurşun, cıva vb.) toprağa ve suya karışarak kirlilik oluşturur."},{"f":"Deterjanların su kirliliğine etkisi nedir?","b":"Sulara karışarak sucul canlıların yaşamını olumsuz etkiler, köpük kirliliğine yol açar."},{"f":"Endüstriyel atıkların çevreye etkisi nedir?","b":"Su ve toprağa karışarak kimyasal kirliliğe neden olur."},{"f":"Kimyasal kirletici nedir?","b":"Doğaya (hava, su, toprak) zarar veren, doğal dengeyi bozan kimyasal madde."},{"f":"Atmosferin canlılar için önemi nedir?","b":"Solunum için gerekli gazları sağlar, zararlı güneş ışınlarını filtreler, sıcaklık dengesini korur."},{"f":"Musluk suyundaki kireçlenmenin nedeni nedir?","b":"Sudaki çözünmüş kalsiyum ve magnezyum bileşiklerinin (su sertliği) çökmesi."},{"f":"Organik sıvı kirleticilere örnek nedir?","b":"Petrol türevleri ve çözücüler gibi suya/toprağa karışan organik kimyasallar."},{"f":"Plastik atıkların çevredeki en büyük sorunu nedir?","b":"Doğada çok uzun sürede parçalanması (biyobozunur olmaması) ve birikerek kirliliğe yol açması."},{"f":"Ağır metal kirliliğine örnek hangi elementler verilebilir?","b":"Kurşun (Pb) ve cıva (Hg)."},{"f":"Kükürt oksitlerin başlıca kaynağı nedir?","b":"Kükürt içeren fosil yakıtların (kömür, petrol) yanması."},{"f":"Azot oksitlerin başlıca kaynağı nedir?","b":"Yüksek sıcaklıkta yanma süreçleri (motorlu taşıtlar, sanayi tesisleri)."},{"f":"Çevre kirliliğini azaltmada bireysel sorumluluk neden önemlidir?","b":"Küçük ölçekli tüketim ve atık tercihleri toplamda çevresel etkiyi azaltabilir."}]},{"id":"kim-6","name":"Kimyanın Temel Kanunları ve Kimyasal Hesaplamalar","cards":[{"f":"Kütlenin korunumu kanununu kim ortaya koymuştur?","b":"Antoine Lavoisier."},{"f":"Kütlenin korunumu kanunu ne der?","b":"Kapalı bir sistemde tepkimeye girenlerin toplam kütlesi, ürünlerin toplam kütlesine eşittir."},{"f":"Sabit oranlar kanunu ne der?","b":"Bir bileşiği oluşturan elementlerin kütlece birleşme oranı her zaman sabittir."},{"f":"Sabit oranlar kanununu kim ortaya koymuştur?","b":"Joseph Proust."},{"f":"Katlı oranlar kanunu ne der?","b":"Aynı iki element birden fazla bileşik oluşturuyorsa, sabit kütledeki elementle birleşen diğer elementin kütleleri arasında basit tam sayı oranı vardır."},{"f":"Katlı oranlar kanununu kim ortaya koymuştur?","b":"John Dalton."},{"f":"Demir(II) sülfür (FeS) elde etme deneyi hangi kanunu örnekler?","b":"Sabit oranlar kanunu; demir ve kükürt her zaman aynı kütle oranında birleşir."},{"f":"Bağıl atom kütlesi nasıl tanımlanır?","b":"Bir atomun kütlesinin, karbon-12 atomunun kütlesinin 1/12'sine oranıdır."},{"f":"İzotop atomların ortalama atom kütlesi neden tam sayı çıkmaz?","b":"Doğada bulunan izotopların oranlarına göre ağırlıklı ortalama alındığı için."},{"f":"Mol kavramı neyi ifade eder?","b":"Belirli sayıda (Avogadro sayısı kadar) tanecik içeren madde miktarı birimi."},{"f":"Yanma tepkimesi nedir?","b":"Bir maddenin oksijenle tepkimeye girmesi."},{"f":"Sentez (oluşum) tepkimesi nedir?","b":"İki veya daha fazla maddenin birleşerek tek bir ürün oluşturması."},{"f":"Analiz (ayrışma) tepkimesi nedir?","b":"Tek bir bileşiğin iki veya daha fazla maddeye ayrışması."},{"f":"Asit-baz tepkimesi nedir?","b":"Bir asit ile bir bazın tepkimeye girerek tuz ve su oluşturması (nötralleşme)."},{"f":"Çözünme-çökelme tepkimesi nedir?","b":"Çözelti içindeki iyonların birleşerek suda çözünmeyen katı bir ürün (çökelek) oluşturması."},{"f":"Kurşun(II) iyodür çökme deneyi hangi tepkime türüne örnektir?","b":"Çözünme-çökelme tepkimesi; sarı renkli PbI₂ çökeleği oluşur."},{"f":"Kimyasal tepkime denklemlerinde denkleştirme neden gereklidir?","b":"Kütlenin korunumu kanunu gereği, eşitliğin iki tarafındaki atom sayılarının eşit olması için."},{"f":"Sınırlayıcı bileşen nedir?","b":"Tepkimede ilk tükenen ve oluşabilecek ürün miktarını belirleyen maddedir."},{"f":"Yüzde verim neyi ifade eder?","b":"Gerçekte elde edilen ürün miktarının, teorik olarak beklenen miktara oranının yüzdesini."},{"f":"Kimyanın temel kanunları hangileridir?","b":"Kütlenin korunumu, sabit oranlar ve katlı oranlar kanunları."}]},{"id":"kim-7","name":"Karışımlar","cards":[{"f":"Homojen karışım nedir?","b":"Her noktasında aynı özelliği gösteren, bileşenlerin birbiri içinde tamamen dağıldığı karışım (çözelti)."},{"f":"Heterojen karışım nedir?","b":"Bileşenlerinin karışım içinde farklı bölgelerde ayırt edilebildiği karışım."},{"f":"Çözücü nedir?","b":"Çözeltide miktarca fazla bulunan, çözünmeyi sağlayan bileşen."},{"f":"Çözünen nedir?","b":"Çözeltide miktarca az bulunan, çözücü içinde dağılan bileşen."},{"f":"Süspansiyon nedir?","b":"Katı bir maddenin bir sıvı içinde çözünmeden dağıldığı heterojen karışım."},{"f":"Emülsiyon nedir?","b":"Birbiri içinde çözünmeyen iki sıvının oluşturduğu heterojen karışım (örn. süt, mayonez)."},{"f":"Aerosol nedir?","b":"Katı veya sıvı taneciklerin bir gaz içinde dağılmasıyla oluşan karışım (örn. sis, sprey)."},{"f":"Kolloid nedir?","b":"Tanecik boyutu homojen karışımdan büyük, heterojen karışımdan küçük olan, gözle ayırt edilemeyen dağılım."},{"f":"Adi karışım nedir?","b":"Bileşenleri, tanecik boyutu büyük olduğu için çıplak gözle veya basit yöntemlerle ayırt edilebilen heterojen karışım."},{"f":"Derişik çözelti nedir?","b":"Çözünen madde oranı yüksek olan çözelti."},{"f":"Seyreltik çözelti nedir?","b":"Çözünen madde oranı düşük olan çözelti."},{"f":"Kütlece yüzde derişim nasıl tanımlanır?","b":"100 g çözeltide çözünmüş olan maddenin gram cinsinden miktarı."},{"f":"Hacimce yüzde derişim nasıl tanımlanır?","b":"100 mL çözeltide çözünenin hacimce oranı."},{"f":"ppm birimi neyi ifade eder?","b":"Çözeltide milyonda bir birim cinsinden çok küçük derişimleri."},{"f":"Çözünme sürecinde hangi etkileşimler rol oynar?","b":"Polarlık, hidrojen bağı ve çözücü-çözünen benzerliği (benzer benzeri çözer ilkesi)."},{"f":"Çözeltilerin donma/kaynama noktası saf çözücüden nasıl farklıdır?","b":"Derişime bağlı olarak değişir; donma noktası düşer, kaynama noktası yükselir."},{"f":"Mıknatısla ayırma hangi fiziksel farktan yararlanır?","b":"Manyetik özellik (mıknatısa çekilme) farkından."},{"f":"Eleme, süzme ve diyaliz hangi fiziksel farktan yararlanır?","b":"Tanecik boyutu farkından."},{"f":"Ayırma hunisi ve yüzdürme hangi fiziksel farktan yararlanır?","b":"Yoğunluk farkından."},{"f":"Basit damıtma ve ayrımsal damıtma hangi fiziksel farktan yararlanır?","b":"Kaynama noktası farkından."},{"f":"Özütleme, kristallendirme ve ayrımsal kristallendirme hangi fiziksel farktan yararlanır?","b":"Çözünürlük farkından."},{"f":"Basit damıtma ile ayrımsal damıtma arasındaki fark nedir?","b":"Basit damıtma tek bileşeni ayırır; ayrımsal damıtma kaynama noktaları birbirine yakın birden fazla sıvıyı ayırır."},{"f":"Özütleme (ekstraksiyon) nedir?","b":"Bir karışımdaki bileşenin uygun bir çözücüyle çekilerek ayrılması."},{"f":"Ayrımsal kristallendirme ne zaman tercih edilir?","b":"Çözünürlükleri sıcaklıkla farklı değişen iki katıyı birbirinden ayırmak için."},{"f":"Diyaliz yönteminde hangi tür zar kullanılır?","b":"Yarı geçirgen zar; küçük tanecikler geçer, büyük tanecikler geçemez."}]},{"id":"kim-8","name":"Asitler, Bazlar ve Tuzlar","cards":[{"f":"Asitlerin ortak özelliklerinden biri nedir?","b":"Ekşi tat, turnusolü kırmızıya çevirme, metallerle tepkimeye girip hidrojen gazı çıkarma."},{"f":"Bazların ortak özelliklerinden biri nedir?","b":"Ele kayganlık hissi verme, turnusolü maviye çevirme, acı tat."},{"f":"Asitler suda çözündüğünde moleküler düzeyde ne oluşturur?","b":"H₃O⁺ (hidronyum) iyonu."},{"f":"Bazlar suda çözündüğünde moleküler düzeyde ne oluşturur?","b":"OH⁻ (hidroksit) iyonu."},{"f":"İndikatör (belirteç) nedir?","b":"Ortamın asit mi baz mı olduğunu renk değişimiyle gösteren madde."},{"f":"Kırmızı lahana suyu neden indikatör olarak kullanılabilir?","b":"Asidik ve bazik ortamlarda farklı renkler alarak ortamın asitlik-bazlığını gösterir."},{"f":"pH kağıdı ne işe yarar?","b":"Bir çözeltinin asitlik-bazlık derecesini renk değişimiyle yaklaşık olarak ölçmeye yarar."},{"f":"pH değeri küçüldükçe ortam nasıl olur?","b":"Daha asidik olur."},{"f":"pH değeri büyüdükçe ortam nasıl olur?","b":"Daha bazik olur."},{"f":"CO₂, SO₂ ve N₂O₅ suyla tepkimeye girdiğinde nasıl davranır?","b":"Asit gibi davranan çözeltiler oluşturur."},{"f":"NH₃ ve CaO suyla tepkimeye girdiğinde nasıl davranır?","b":"Baz gibi davranan çözeltiler oluşturur."},{"f":"Nötralleşme tepkimesinin ürünleri nelerdir?","b":"Tuz ve su."},{"f":"Sodyum hidroksit ile sülfürik asit tepkimeye girerse hangi tuz oluşur?","b":"Sodyum sülfat."},{"f":"Aktif metal nedir?","b":"Asitlerle kolayca tepkimeye girip hidrojen gazı çıkaran, reaktifliği yüksek metal (örn. sodyum, potasyum)."},{"f":"Soy metal nedir?","b":"Asitlerle kolay kolay tepkimeye girmeyen, reaktifliği çok düşük metal (örn. altın, platin)."},{"f":"Yarı soy metal nedir?","b":"Aktif metal ile soy metal arası reaktiflikte olan metal (örn. bakır, gümüş)."},{"f":"Amfoter metal nedir?","b":"Hem asitlerle hem bazlarla tepkimeye girebilen metal (örn. alüminyum, çinko)."},{"f":"Hangi asit camı ve porseleni aşındırabilir?","b":"Hidroflorik asit (HF)."},{"f":"Derişik sülfürik asidin tehlikeli özelliği nedir?","b":"Güçlü nem çekme (higroskopik) özelliği ve çözünürken yüksek ısı açığa çıkarması."},{"f":"Çamaşır suyu ile tuz ruhu (HCl) neden birlikte kullanılmamalıdır?","b":"Karıştıklarında zehirli klor gazı açığa çıkabilir."},{"f":"Asit yağmurlarının tarihi eserlere etkisi nedir?","b":"İçerdiği asitler taş ve metal yapıları aşındırarak zamanla tahrip eder."},{"f":"Kostiğin (NaOH) cilt ve saça etkisi nasıldır?","b":"Yakıcı ve tahriş edicidir, dokulara zarar verebilir."},{"f":"Sodyum klorürün kullanım alanı nedir?","b":"Sofra tuzu olarak gıdalarda, ayrıca endüstride kullanılır."},{"f":"Sodyum karbonatın kullanım alanı nedir?","b":"Çamaşır sodası olarak temizlikte ve cam üretiminde kullanılır."},{"f":"Sodyum bikarbonatın kullanım alanı nedir?","b":"Kabartma tozu olarak gıdalarda, ayrıca mide asidini nötralleştirmede kullanılır."},{"f":"Kalsiyum karbonatın kullanım alanı nedir?","b":"Kireçtaşı/mermer olarak inşaatta, ayrıca mide ilaçlarında kullanılır."},{"f":"Amonyum klorürün kullanım alanı nedir?","b":"Nişadır olarak lehimlemede ve bazı pillerde kullanılır."},{"f":"Alüminyumun amfoterlik özelliği ne anlama gelir?","b":"Hem asitlerle hem bazlarla tepkimeye girerek çözünebilmesi."}]},{"id":"kim-9","name":"Kimya Her Yerde","cards":[{"f":"Yüzey aktif madde (surfaktan) nedir?","b":"Bir ucu suyu seven (polar), bir ucu yağı seven (apolar) yapısıyla kiri sudan uzaklaştırabilen madde."},{"f":"Sabun ve deterjanların kirleri temizleme prensibi nedir?","b":"Apolar uçlarıyla yağ/kiri, polar uçlarıyla suyu tutarak kirin suyla uzaklaştırılmasını sağlarlar."},{"f":"Ağartıcı olarak yaygın kullanılan madde hangisidir?","b":"Çamaşır suyu (sodyum hipoklorit)."},{"f":"Hijyen amacıyla kullanılan temizlik maddelerine örnek nedir?","b":"Çamaşır suyu, kireç kaymağı."},{"f":"Monomer nedir?","b":"Polimer zincirini oluşturan tekrar eden küçük yapı birimi."},{"f":"Polimer nedir?","b":"Çok sayıda monomerin birbirine bağlanmasıyla oluşan büyük moleküllü madde."},{"f":"Kauçuğun başlıca kullanım alanı nedir?","b":"Lastik ve esnek malzeme üretimi."},{"f":"Polietilen (PE) nerelerde kullanılır?","b":"Poşet ve plastik şişe üretiminde."},{"f":"Polietilen tereftalat (PET) nerelerde kullanılır?","b":"İçecek şişelerinde."},{"f":"Kevlar hangi özelliğiyle bilinir ve nerede kullanılır?","b":"Çok yüksek dayanıklılığıyla; kurşun geçirmez yelek gibi koruyucu malzemelerde kullanılır."},{"f":"Polivinil klorür (PVC) nerelerde kullanılır?","b":"Boru ve kablo kaplamalarında."},{"f":"Teflon (politetraflor eten) nerede kullanılır?","b":"Yapışmaz tava kaplamalarında."},{"f":"Polistiren (PS) nerelerde kullanılır?","b":"Köpük ambalaj malzemelerinde."},{"f":"Polimer, kağıt, cam ve metal geri dönüşümünün faydası nedir?","b":"Doğal kaynakların korunması ve ülke ekonomisine katkı sağlaması."},{"f":"Kozmetik ürünlerde zararlı olabilecek kimyasallara hangi ürünler örnek verilir?","b":"Parfüm, saç boyası, kalıcı dövme boyası, jöle."},{"f":"İlaçların piyasadaki başlıca formları nelerdir?","b":"Hap, şurup, iğne, merhem."},{"f":"Yanlış/gereksiz ilaç kullanımının zararı nedir?","b":"İnsan sağlığına, ülke ekonomisine ve çevreye zarar verir."},{"f":"Hazır gıdalarda bulunabilen katkı türleri nelerdir?","b":"Koruyucular, renklendiriciler, emülsiyonlaştırıcılar, tatlandırıcılar."},{"f":"Pastörizasyon nedir?","b":"Gıdalardaki zararlı mikroorganizmaları belirli sıcaklıkta ısıtarak azaltma işlemi."},{"f":"UHT süt nedir?","b":"Çok yüksek sıcaklıkta kısa süreli ısıtılarak dayanıklı hale getirilmiş süt."},{"f":"Katı yağlara örnek nedir?","b":"Tereyağı, margarin."},{"f":"Sıvı yağlara örnek nedir?","b":"Zeytinyağı, ayçiçek yağı, mısır özü yağı, fındık yağı."},{"f":"Sızma zeytinyağı ne anlama gelir?","b":"İlk sıkımda, herhangi bir işlem/rafinasyon görmeden elde edilen zeytinyağı."},{"f":"Rafine yağ nedir?","b":"Arıtma işlemlerinden geçirilerek koku, renk ve tat açısından saflaştırılmış yağ."},{"f":"Şampuan, diş macunu, katı ve sıvı sabun neden kişisel temizlik ürünüdür?","b":"Yüzey aktif maddeler içererek kir ve yağı temizlemeye yardımcı olurlar."},{"f":"Hazır gıda etiketlerinde nelere dikkat edilmelidir?","b":"Üretim ve son kullanma tarihine, içerik ve katkı maddesi bilgisine."},{"f":"Oyuncak ve tekstil ürünlerinde kullanılan polimer malzemelerin olası zararı nedir?","b":"İçerdikleri bazı kimyasallar (ör. yumuşatıcılar) sağlığa zarar verebilir."},{"f":"Apolar grup kavramı hangi bağlamda geçer?","b":"Sabun/deterjan moleküllerinin yağı tutan, suyu sevmeyen kısmı."},{"f":"Polar uç kavramı hangi bağlamda geçer?","b":"Sabun/deterjan moleküllerinin suyu tutan, suyu seven kısmı."},{"f":"Vinterize yağ ne anlama gelir?","b":"Soğukta bulanıklaşmaması için düşük sıcaklıkta katılaşan bileşenleri ayrılmış yağ."}]}]},{"subject":"Biyoloji","units":[{"id":"biy-1","name":"Canlıların Ortak Özellikleri","cards":[{"f":"Canlıların ortak özellikleri nelerdir?","b":"Hücresel yapı, beslenme, solunum, boşaltım, hareket, uyarılara tepki, metabolizma, homeostazi, uyum, organizasyon, üreme, büyüme ve gelişme."},{"f":"Metabolizma nedir?","b":"Hücrede gerçekleşen yapım (anabolik) ve yıkım (katabolik) tepkimelerinin tümüdür."},{"f":"Anabolizma ile katabolizma arasındaki fark nedir?","b":"Anabolizma enerji harcayarak küçük moleküllerden büyük molekül yapar; katabolizma büyük molekülleri parçalayıp enerji açığa çıkarır."},{"f":"Homeostazi nedir?","b":"Canlının dış ortam değişse bile iç ortamını (sıcaklık, pH, su-tuz dengesi vb.) sabit tutabilme yeteneğidir."},{"f":"Canlı organizasyon basamakları küçükten büyüğe nasıl sıralanır?","b":"Hücre, doku, organ, sistem, organizma, popülasyon, komünite, ekosistem, biyom, biyosfer."},{"f":"Boşaltım neden canlıların ortak bir özelliğidir?","b":"Metabolizma sonucu oluşan zararlı ya da fazla atık maddelerin vücuttan uzaklaştırılması gerekir."},{"f":"Büyüme ile gelişme arasındaki fark nedir?","b":"Büyüme hücre sayısı ve boyut artışıdır; gelişme ise yapısal ve işlevsel olgunlaşmadır (farklılaşmadır)."},{"f":"Canlılarda uyum (adaptasyon) ne demektir?","b":"Canlının yaşadığı ortamda hayatta kalmasını ve üremesini kolaylaştıran özellikler kazanmasıdır."},{"f":"Üreme neden canlıların ortak özelliği sayılır?","b":"Türün nesiller boyunca devamını sağlayan temel yaşamsal olaydır."},{"f":"Solunum canlılar için neden gereklidir?","b":"Besinlerdeki kimyasal enerjiyi hücrenin kullanabileceği ATP enerjisine dönüştürmek için gereklidir."},{"f":"Hareket özelliği sadece yer değiştirme midir?","b":"Hayır; bitkilerde yer değiştirme olmasa da ışığa yönelme gibi yer değiştirmeyen hareketler görülür."},{"f":"Canlıların hücresel yapıda olması ne anlama gelir?","b":"Her canlı en az bir hücreden oluşur; hücre yaşamın en küçük yapısal ve işlevsel birimidir."},{"f":"Kontrollü bir deneyde bağımsız değişken nedir?","b":"Deneyi yapanın kasıtlı olarak değiştirdiği, etkisi araştırılan değişkendir."},{"f":"Kontrollü bir deneyde bağımlı değişken nedir?","b":"Bağımsız değişkene bağlı olarak değişen ve ölçülen sonuçtur."},{"f":"Kontrol grubu ne işe yarar?","b":"Test edilen değişken dışında her koşulun aynı tutulduğu, karşılaştırma yapılan gruptur."},{"f":"Robert Hooke hücre teorisine nasıl katkı sağlamıştır?","b":"Mikroskopla mantar dokusunu inceleyip küçük boşlukları ilk kez hücre olarak adlandırmıştır."},{"f":"Rudolf Virchow'un hücre teorisine katkısı nedir?","b":"Her hücrenin daha önceden var olan bir hücrenin bölünmesiyle oluştuğunu ileri sürmüştür."},{"f":"Metabolizma hızını etkileyen faktörlere örnek ver.","b":"Vücut sıcaklığı, hormon düzeyi, yaş ve fiziksel aktivite düzeyi metabolizma hızını etkiler."},{"f":"Canlılarda uyarılara tepki özelliğine örnek ver.","b":"Bitkinin ışığa doğru yönelmesi veya bir hayvanın ani sese tepki olarak kaçması."},{"f":"Biyoloji bilimi neyi inceler?","b":"Canlıları, canlıların yapısını, işlevlerini ve birbirleriyle-çevreyle ilişkilerini inceleyen bilim dalıdır."},{"f":"Bir hücrenin organizasyon özelliği ne demektir?","b":"Hücre içindeki yapı ve organellerin uyum içinde, düzenli bir bütün oluşturmasıdır."},{"f":"Canlılarda büyüme hangi temel hücresel olayla gerçekleşir?","b":"Hücre sayısının mitoz bölünmeyle artması ve/veya hücre hacminin büyümesiyle gerçekleşir."}]},{"id":"biy-2","name":"Canlıların Temel Bileşenleri","cards":[{"f":"Su canlılar için neden önemlidir?","b":"Polar bir moleküldür, iyi bir çözücüdür, hücre içi tepkimelerin ortamını oluşturur ve sıcaklık dengesine yardımcı olur."},{"f":"İnorganik ve organik bileşik arasındaki fark nedir?","b":"İnorganik bileşikler (su, mineral, asit, baz, tuz) canlıların dışarıdan hazır aldığı maddelerdir; organik bileşikler (karbonhidrat, protein, lipit, vitamin, nükleik asit) karbon iskeletlidir ve canlılar tarafından üretilebilir."},{"f":"Mineraller yakıldığında neden kül olarak kalır?","b":"Mineraller inorganik olduğu için yanmaz; organik kısım yanınca geriye mineral kalıntısı (kül) kalır."},{"f":"Kalsiyumun canlılar için önemi nedir?","b":"Kemik ve diş yapısına katılır; kas kasılması ve kanın pıhtılaşmasında rol oynar."},{"f":"Demir eksikliği hangi rahatsızlığa yol açar?","b":"Kansızlığa (anemi) yol açar; demir, hemoglobinin oksijen taşıyan yapısında bulunur."},{"f":"İyot eksikliğinde hangi hastalık görülür?","b":"Guatr görülür; iyot tiroid bezinin hormon üretimi için gereklidir."},{"f":"Sodyum ve potasyum canlılarda hangi işlevde önemlidir?","b":"Sinir hücrelerinde uyartı iletimini ve hücre içi-dışı su/madde dengesini sağlarlar."},{"f":"Fosforun canlılardaki önemi nedir?","b":"Kemik ve diş yapısına katılır; ayrıca ATP ve nükleik asitlerin (DNA, RNA) yapısında bulunur."},{"f":"Florun canlılar için önemi nedir?","b":"Diş minesini güçlendirerek diş çürümesine karşı koruma sağlar."},{"f":"Karbonhidratların yapı taşı nedir?","b":"Monosakkaritlerdir (basit şekerler); örnek: glikoz."},{"f":"Monosakkarit-disakkarit-polisakkarit farkı nedir?","b":"Monosakkarit tek şeker biriminden, disakkarit iki birimin, polisakkarit çok sayıda birimin birleşmesinden oluşur."},{"f":"Hayvan ve mantar hücreleri fazla glikozu nasıl depolar?","b":"Glikojen şeklinde depolar."},{"f":"Bitkiler fazla glikozu nasıl depolar?","b":"Nişasta şeklinde depolar."},{"f":"Selülozun görevi nedir?","b":"Bitki hücre duvarının yapı taşıdır; insan sindirim sisteminde sindirilemeyen bir lif kaynağıdır."},{"f":"Proteinlerin yapı taşı nedir ve aralarında hangi bağ bulunur?","b":"Amino asitlerdir; amino asitler arasında peptit bağı bulunur."},{"f":"Bazı amino asitler için vücutta üretilemez ifadesi ne anlama gelir?","b":"Bu amino asitler besinlerle dışarıdan alınmak zorundadır; vücut kendisi sentezleyemez."},{"f":"Enzimlerin temel özellikleri nelerdir?","b":"Protein yapılı biyokatalizördürler, tepkimeye özgüdürler, tepkime sonunda yapıları değişmez ve tekrar kullanılabilirler."},{"f":"Enzim aktivitesini etkileyen faktörler nelerdir?","b":"Sıcaklık, ortam pH'ı ve madde (substrat/enzim) derişimi enzim aktivitesini etkiler."},{"f":"Enzimler yüksek sıcaklıkta neden görev yapamaz hale gelir?","b":"Yüksek sıcaklık enzimin yapısını bozar (denatürasyon), bu yüzden görevini yapamaz."},{"f":"Yağda çözünen vitaminler hangileridir?","b":"A, D, E ve K vitaminleridir; fazlası vücutta (karaciğer ve yağ dokusunda) depolanabilir."},{"f":"Suda çözünen vitaminler hangileridir?","b":"B grubu vitaminleri ve C vitaminidir; vücutta depolanmaz, fazlası idrarla atılır."},{"f":"D vitamini eksikliğinde ne görülür?","b":"Kemik gelişim bozukluğu (raşitizm) görülebilir."},{"f":"Nükleik asitlerin yapı taşı nedir?","b":"Nükleotidlerdir (şeker, fosfat ve azotlu bazdan oluşur)."},{"f":"DNA tüm canlı türlerinde ortak olan hangi özelliğe sahiptir?","b":"Tüm canlı türlerinde bulunur ve aynı çeşit nükleotidlerden yapılmıştır."},{"f":"DNA ile RNA arasındaki temel fark nedir?","b":"DNA çift zincirli ve şekeri deoksiribozdur; RNA tek zincirli ve şekeri ribozdur."},{"f":"ATP canlılar için neden önemlidir?","b":"Hücrenin yaşamsal faaliyetlerinde kullandığı temel enerji taşıyıcı molekülüdür."},{"f":"Hormonların canlılardaki görevi nedir?","b":"Belirli bezlerden salgılanıp kana karışan, hedef organlarda özel etkiler oluşturan kimyasal habercilerdir."}]},{"id":"biy-3","name":"Hücre ve Madde Geçişleri","cards":[{"f":"Hücre teorisine göre canlılığın temel birimi nedir?","b":"Hücredir; tüm canlılar hücrelerden oluşur."},{"f":"Prokaryot hücre ile ökaryot hücre arasındaki temel fark nedir?","b":"Prokaryot hücrede zarla çevrili çekirdek ve zarlı organel bulunmaz; ökaryot hücrede bulunur."},{"f":"Hangi canlı grupları prokaryot hücre yapısındadır?","b":"Bakteriler ve arkeler prokaryot hücre yapısındadır."},{"f":"Ribozomun görevi nedir?","b":"Protein sentezi yapar; hem prokaryot hem ökaryot hücrelerde bulunan zarsız bir yapıdır."},{"f":"Mitokondrinin görevi nedir?","b":"Oksijenli solunum yaparak hücrenin ihtiyaç duyduğu ATP'nin büyük kısmını üretir."},{"f":"Golgi aygıtının görevi nedir?","b":"Endoplazmik retikulumdan gelen madde ve proteinleri işler, paketler ve hücre içindeki bölgelere gönderir."},{"f":"Lizozomun görevi nedir?","b":"Hayvan hücrelerinde hücre içi sindirimi gerçekleştirir."},{"f":"Kloroplastın görevi nedir?","b":"Işık enerjisini kullanarak fotosentezle besin (organik madde) ve oksijen üretir."},{"f":"Hücre iskeletinin görevi nedir?","b":"Hücrenin şeklinin oluşmasını ve korunmasını sağlar; hücre bölünmesi gibi olaylarda da görev alır."},{"f":"Sentrozom hangi hücrelerde bulunur ve görevi nedir?","b":"Hayvan hücrelerinde bulunur; hücre bölünmesinde görev alır."},{"f":"Kofulun (vakuolün) görevi nedir?","b":"Su, besin ve atık maddelerin depolanmasını veya dışarı atılmasını sağlar."},{"f":"Bitki ve hayvan hücresi arasındaki üç temel fark nedir?","b":"Bitki hücresinde hücre duvarı, büyük koful ve kloroplast bulunur; hayvan hücresinde bunlar bulunmaz."},{"f":"Mitokondri ve kloroplastın ortak özelliği nedir?","b":"İkisi de çift zarla çevrilidir ve kendilerine ait DNA'ya sahiptir."},{"f":"Hücre zarının genel yapısı nasıldır?","b":"Akıcı mozaik model ile açıklanır; çift katlı yağ tabakası içine gömülü proteinlerden oluşur."},{"f":"Hücre zarının seçici geçirgen olması ne demektir?","b":"Bazı maddelerin serbestçe, bazılarının ise sınırlı ya da hiç geçmediği bir zar özelliğidir."},{"f":"Difüzyon nedir?","b":"Küçük moleküllerin yoğun olduğu ortamdan az yoğun olduğu ortama, enerji harcanmadan geçişidir."},{"f":"Osmoz nedir?","b":"Suyun yarı geçirgen bir zardan az yoğun (hipotonik) ortamdan çok yoğun (hipertonik) ortama geçişidir."},{"f":"Aktif taşıma difüzyondan nasıl farklıdır?","b":"Aktif taşımada madde derişim farkına karşı, ATP harcanarak taşınır; difüzyonda enerji harcanmaz."},{"f":"İzotonik ortama bırakılan bir hücrede su alışverişi nasıl olur?","b":"Hücre içi ve dışı yoğunluk eşit olduğu için gözle görülür bir değişiklik olmaz."},{"f":"Hipotonik ortama konan bir hayvan hücresine ne olur?","b":"Hücre su alır, şişer ve aşırı su alımı hücrenin patlamasına (hemolize) yol açabilir."},{"f":"Hipertonik ortama konan bir bitki hücresine ne olur?","b":"Hücre su kaybeder, sitoplazma hücre çeperinden ayrılır (plazmoliz)."},{"f":"Turgor hali nedir?","b":"Bitki hücresinin hipotonik ortamda su alarak şişkin ve diri bir hal almasıdır."},{"f":"Endositoz nedir?","b":"Hücrenin büyük parçacıkları, zarını içe katlayarak ATP harcayıp hücre içine almasıdır."},{"f":"Fagositoz ile pinositoz arasındaki fark nedir?","b":"Fagositoz katı parçacıkların, pinositoz ise sıvı damlacıklarının hücre içine alınmasıdır."},{"f":"Ekzositoz nedir?","b":"Hücre içindeki maddelerin kese içinde hücre zarına taşınıp dışarı atılmasıdır; ATP harcanır."},{"f":"Hücre zarından madde geçişini etkileyen faktörler nelerdir?","b":"Ortamın sıcaklığı, derişim (konsantrasyon) farkı ve zarın yüzey alanı madde geçiş hızını etkiler."}]},{"id":"biy-4","name":"Canlılar Dünyası ve Sınıflandırma","cards":[{"f":"Sınıflandırmada kullanılan basamaklar (büyükten küçüğe) nelerdir?","b":"Âlem, şube, sınıf, takım, aile (familya), cins, tür."},{"f":"Sistematik birimlerin en büyüğü hangisidir?","b":"Âlemdir; en fazla canlı türünü içine alan sınıflandırma basamağıdır."},{"f":"Tür nedir?","b":"Ortak bir atadan gelen, doğal koşullarda çiftleştiğinde verimli döller verebilen bireyler topluluğudur."},{"f":"İkili adlandırma sistemini kim geliştirmiştir?","b":"Carolus Linnaeus geliştirmiştir; canlı adı Cins türadı biçiminde yazılır (örn. Homo sapiens)."},{"f":"Sınıflandırmada cins basamağı ne ifade eder?","b":"Birbirine benzer ve ortak birçok özelliği olan türler topluluğudur."},{"f":"Canlıların sınıflandırılmasında kullanılan 6 alem hangileridir?","b":"Bakteriler, Arkeler, Protistler, Bitkiler, Mantarlar, Hayvanlar."},{"f":"Alemler daha büyük hangi gruplarda toplanır?","b":"Bakteri, Arke ve Ökaryot olmak üzere 3 büyük domain (üst âlem) grubunda toplanır."},{"f":"Bakteriler âleminin genel özellikleri nelerdir?","b":"Prokaryot ve tek hücrelidirler; DNA'ları halka şeklindedir, fazla karbonhidratı glikojen olarak depolarlar."},{"f":"Arkelerin bakterilerden ayrılan özelliği nedir?","b":"Arkelerin hücre duvarında peptidoglikan bulunmaz; genellikle sıra dışı (aşırı) ortamlarda yaşarlar."},{"f":"Protistler âleminin genel özelliği nedir?","b":"Ökaryot hücre yapısına sahiptirler; tek hücreli veya çok hücreli (örn. algler) olabilirler."},{"f":"Bitkiler âleminin genel özellikleri nelerdir?","b":"Ökaryot, çok hücreli, hücre duvarı selülozdan yapılı, fotosentezle kendi besinini üreten canlılardır."},{"f":"Bitkiler fotosentez ürünü glikozu nasıl depolar?","b":"Nişasta olarak depolar."},{"f":"Mantarlar âleminin genel özellikleri nelerdir?","b":"Ökaryot, hücre duvarı kitin yapılıdır, glikojen depolar ve hazır organik maddeyle beslenir."},{"f":"Mantarların doğadaki en önemli görevlerinden biri nedir?","b":"Organik atıkları inorganik maddelere dönüştüren ayrıştırıcı olarak madde döngüsüne katkı sağlarlar."},{"f":"Hayvanlar âleminin genel özellikleri nelerdir?","b":"Ökaryot, çok hücreli, hücre duvarı yok, hazır besinle (heterotrof) beslenen canlılardır."},{"f":"Hayvanlar âlemi sınıflandırılırken dikkate alınan ilk ölçüt nedir?","b":"Omurga varlığıdır; hayvanlar bu ölçüte göre omurgalı ve omurgasız olarak ikiye ayrılır."},{"f":"Omurgasız hayvan gruplarına örnek ver (en az 4).","b":"Süngerler, sölenterler, solucanlar, yumuşakçalar, eklem bacaklılar, derisi dikenliler."},{"f":"Omurgalı hayvan gruplarını sırala.","b":"Balıklar, iki yaşamlılar, sürüngenler, kuşlar, memeliler."},{"f":"Bitkiler âlemi hangi iki ana gruba ayrılır?","b":"Tohumsuz (sporlu) bitkiler ve tohumlu bitkiler; tohumlu bitkiler de açık tohumlu ve kapalı tohumlu olarak ayrılır."},{"f":"Virüsler neden bir canlı âlemine dahil edilmez?","b":"Hücresel yapıya sahip değildirler, tek başlarına metabolizma yürütemez ve üreyemezler."},{"f":"Virüsler nasıl çoğalır?","b":"Ancak girdikleri bir konak hücrenin yapılarını (enzim, ribozom, ATP vb.) kullanarak çoğalabilirler."},{"f":"Virüslerin neden olduğu hastalıklara örnek ver.","b":"Kuduz, hepatit, grip, uçuk ve AIDS virüslerin neden olduğu hastalıklardandır."},{"f":"Virüslere karşı neden antibiyotik etkisizdir?","b":"Antibiyotikler bakterilere özgü yapı ve enzim sistemlerini hedef alır; virüslerde böyle bir sistem yoktur."},{"f":"Canlıların sınıflandırılmasına bilim insanları neden farklı ölçüt kullanır?","b":"Canlı çeşitliliği çok büyük olduğu için sınıflandırma zamanla yeni bulgularla sınanır, düzeltilir ve yenilenir."}]},{"id":"biy-5","name":"Hücre Bölünmeleri ve Üreme","cards":[{"f":"Hücre bölünmesi canlılar için neden gereklidir?","b":"Büyüme, gelişme, onarım (yara iyileşmesi) ve üreme için gereklidir."},{"f":"Mitoz sonucunda kaç yavru hücre oluşur ve bunlar ana hücreyle nasıl bir ilişkidedir?","b":"2 yavru hücre oluşur; bu hücreler ana hücre ile genetik olarak aynıdır (kromozom sayısı korunur)."},{"f":"İnterfazda hücrede temel olarak ne gerçekleşir?","b":"Hücre büyür ve bölünme öncesi DNA kendini eşler (replikasyon yapar)."},{"f":"Mitozun evrelerini sırayla say.","b":"Profaz, metafaz, anafaz, telofaz; öncesinde interfaz vardır."},{"f":"Profaz evresinde ne olur?","b":"Kromatin iplikler kısalıp kalınlaşarak kromozomları oluşturur, çekirdek zarı kaybolmaya başlar."},{"f":"Metafaz evresinde ne olur?","b":"Kromozomlar hücrenin ortasına (ekvatoral düzleme) dizilir."},{"f":"Anafaz evresinde ne olur?","b":"Kardeş kromatidler birbirinden ayrılıp hücrenin zıt kutuplarına çekilir."},{"f":"Telofaz evresinde ne olur?","b":"Çekirdek zarı yeniden oluşur ve sitoplazma bölünmesi (sitokinez) başlar."},{"f":"Hücre bölünmesinin kontrolden çıkması hangi hastalıkla ilişkilidir?","b":"Kanserle ilişkilidir; kontrolsüz ve düzensiz hücre çoğalması sonucu oluşur."},{"f":"Eşeysiz üreme çeşitlerine örnek ver (en az 4).","b":"Bölünerek üreme, tomurcuklanma, sporla üreme, rejenerasyon, partenogenez, bitkilerde vejetatif üreme."},{"f":"Partenogenez nedir?","b":"Döllenmemiş yumurta hücresinin gelişerek doğrudan yeni bir birey oluşturmasıdır (bazı arı ve karınca türlerinde görülür)."},{"f":"Rejenerasyon nedir?","b":"Bir canlının kopan bir parçasından yeni bir birey oluşturabilmesidir (örn. planarya)."},{"f":"Vejetatif üreme nedir?","b":"Bitkilerin kök, gövde veya yaprak gibi kısımlarından eşeysiz olarak yeni birey oluşturmasıdır."},{"f":"Mayozun temel amacı nedir?","b":"Üreme hücrelerinin (gamet) oluşmasını sağlamak ve kromozom sayısını yarıya indirmektir."},{"f":"Mayoz sonunda kaç hücre oluşur ve kromozom sayıları nasıldır?","b":"4 yavru hücre oluşur; her biri ana hücrenin yarısı kadar kromozoma (haploit, n) sahiptir."},{"f":"Diploit (2n) ve haploit (n) ne demektir?","b":"Diploit kromozomların çift takım hâlinde bulunması, haploit ise tek takım hâlinde bulunmasıdır."},{"f":"Mayoza özgü olup mitozda görülmeyen olay nedir?","b":"Krossing over (parça değişimi); homolog kromozomlar arasında gerçekleşir ve genetik çeşitliliği artırır."},{"f":"Sinapsis ve tetrat kavramları neyi ifade eder?","b":"Sinapsis homolog kromozomların eşleşmesi, tetrat bu eşleşme sonucu oluşan dört kromatitlik yapıdır."},{"f":"Mitoz ile mayoz arasındaki temel fark nedir?","b":"Mitoz vücut hücrelerinde 2 hücre oluştururken, mayoz üreme ana hücrelerinde 4 hücre oluşturur ve genetik çeşitlilik sağlar."},{"f":"Eşeyli üreme neye dayanır?","b":"Mayoz ile oluşan gametlerin döllenme yoluyla birleşmesine dayanır."},{"f":"Döllenme (fertilizasyon) nedir?","b":"Erkek ve dişi üreme hücrelerinin (gametlerin) birleşerek zigotu oluşturmasıdır."},{"f":"Eşeyli üremenin eşeysiz üremeye göre avantajı nedir?","b":"Yavrularda genetik çeşitlilik sağlayarak türün değişen çevre koşullarına uyumunu kolaylaştırır."},{"f":"Eşeysiz üremenin avantajı nedir?","b":"Tek ebeveyn yeterlidir; hızlı ve kısa sürede çok sayıda birey üretilebilir."},{"f":"Bitkilerde çelikle üretme hangi üreme çeşidine örnektir?","b":"Vejetatif (eşeysiz) üremeye örnektir; tarım ve bahçecilikte yaygın kullanılır."}]},{"id":"biy-6","name":"Kalıtım","cards":[{"f":"Gregor Mendel neden önemlidir?","b":"Bezelye bitkileri üzerinde yaptığı deneylerle kalıtımın genler aracılığıyla nesilden nesile aktarıldığını ilk gösteren bilim insanıdır."},{"f":"Gen ve alel kavramlarını tanımla.","b":"Gen bir özelliği belirleyen kalıtım birimidir; alel ise bir genin farklı biçimlerinden her biridir."},{"f":"Genotip ve fenotip arasındaki fark nedir?","b":"Genotip bireyin sahip olduğu alel yapısıdır (örn. Aa); fenotip bu yapının dışa yansıyan gözlenebilir hâlidir."},{"f":"Homozigot ve heterozigot ne demektir?","b":"Homozigot bir özellik için aynı alellere (AA/aa), heterozigot farklı alellere (Aa) sahip olma durumudur."},{"f":"Baskın (dominant) ve çekinik (resesif) alel arasındaki fark nedir?","b":"Baskın alel heterozigot bireyde bile fenotipte görülür; çekinik alel yalnızca homozigot durumda görülür."},{"f":"Otozom ve gonozom arasındaki fark nedir?","b":"Otozomlar eşey belirlemeyen kromozomlardır; gonozomlar (eşey kromozomları) bireyin eşeyini belirler."},{"f":"Monohibrit çaprazlama nedir?","b":"Tek bir karakter (özellik) bakımından yapılan çaprazlamadır."},{"f":"Dihibrit çaprazlama nedir?","b":"İki farklı karakterin birlikte incelendiği çaprazlamadır."},{"f":"Aa x Aa (monohibrit) çaprazlamasının fenotip oranı nedir?","b":"3 baskın : 1 çekinik oranı elde edilir (genotipte 1:2:1)."},{"f":"Kontrol (test) çaprazlaması ne amaçla yapılır?","b":"Baskın fenotipli bir bireyin homozigot mu heterozigot mu olduğunu anlamak için, o birey homozigot çekinik bireyle çaprazlanır."},{"f":"Punnett karesi ne işe yarar?","b":"Bir çaprazlama sonucunda oluşabilecek genotip ve fenotip olasılıklarını görsel olarak hesaplamaya yarar."},{"f":"Eş baskınlık (kodominantlık) nedir?","b":"Heterozigot bireyde iki farklı alelin de, birbirine karışmadan fenotipte ayrı ayrı görülmesidir."},{"f":"Çok alellilik nedir, hangi örnekle ilişkilendirilir?","b":"Bir genin ikiden fazla alelinin bulunmasıdır; kan grubu (ABO sistemi) ile ilişkilendirilir."},{"f":"ABO kan grubu sisteminde kaç alel bulunur?","b":"Üç alel bulunur: I^A, I^B ve i."},{"f":"AB kan grubu hangi kalıtım şekline örnektir?","b":"Eş baskınlığa (kodominantlığa) örnektir; I^A ve I^B aleli birlikte, karışmadan ifade edilir."},{"f":"Eşeye bağlı kalıtım nedir?","b":"Genin eşey kromozomu (X ya da Y) üzerinde taşınmasıyla ortaya çıkan kalıtım şeklidir."},{"f":"Hemofili nasıl kalıtılır?","b":"X kromozomu üzerinde çekinik olarak kalıtılan bir kan pıhtılaşma bozukluğudur; erkeklerde daha sık görülür."},{"f":"Kısmi renk körlüğü nasıl kalıtılır?","b":"X kromozomu üzerinde çekinik olarak kalıtılır; bu yüzden erkeklerde kadınlara göre daha sık görülür."},{"f":"Eşeye bağlı kalıtım yalnızca X kromozomunda mı görülür?","b":"Hayır; eşeye bağlı kalıtım Y kromozomu üzerinde de görülebilir."},{"f":"Akraba evliliği kalıtsal hastalık riskini neden artırır?","b":"Akraba bireylerin ortak atadan gelen aynı çekinik aleli taşıma olasılığı daha yüksektir."},{"f":"Soyağacında kare ve daire hangi bireyi temsil eder?","b":"Kare erkek bireyi, daire ise dişi bireyi temsil eder."},{"f":"Genetik varyasyonun (çeşitliliğin) başlıca kaynakları nelerdir?","b":"Mutasyon, mayozdaki krossing over ve kromozomların bağımsız dağılımı ile döllenmede gametlerin rastgele birleşmesi."},{"f":"Mutasyon nedir?","b":"DNA'da meydana gelen, sonraki nesillere aktarılabilen kalıtsal değişikliklerdir."},{"f":"Biyolojik çeşitlilik neden bireylerin genotipiyle ilişkilidir?","b":"Popülasyondaki bireyler arasındaki genotip farklılıkları, biyolojik çeşitliliğin temel kaynağıdır."}]},{"id":"biy-7","name":"Ekosistem Ekolojisi ve Çevre Sorunları","cards":[{"f":"Ekosistem nedir?","b":"Belirli bir alandaki canlılar (biyotik) ile bunların cansız çevresinin (abiyotik) birlikte oluşturduğu bütündür."},{"f":"Popülasyon, komünite ve ekosistem arasındaki ilişki nedir?","b":"Popülasyon aynı türden bireyler topluluğu, komünite farklı popülasyonların bir aradalığı, ekosistem ise komünite ile abiyotik çevrenin bütünüdür."},{"f":"Üretici, tüketici ve ayrıştırıcıların ekosistemdeki rolleri nedir?","b":"Üreticiler organik madde üretir, tüketiciler hazır organik besinle beslenir, ayrıştırıcılar ölü madde ve atıkları inorganik maddeye dönüştürür."},{"f":"Besin zinciri ile besin ağı arasındaki fark nedir?","b":"Besin zinciri tek yönlü ve doğrusaldır; besin ağı birden çok besin zincirinin birbirine bağlanmasıyla oluşan karmaşık yapıdır."},{"f":"Enerji piramidinde enerji nasıl aktarılır?","b":"Enerjinin büyük bölümü her basamakta solunum ve ısı kaybıyla azalır; bir üst basamağa yalnızca küçük bir kısmı aktarılır."},{"f":"Madde döngüsü ile enerji akışı arasındaki fark nedir?","b":"Madde (karbon, azot, su vb.) ekosistemde tekrar tekrar kullanılarak döner; enerji ise tek yönlü akar ve sonunda ısı olarak kaybolur."},{"f":"Karbon döngüsünde fotosentez ve solunumun rolü nedir?","b":"Fotosentez atmosferdeki karbondioksiti organik maddeye bağlar; solunum bu karbonu tekrar karbondioksit olarak atmosfere verir."},{"f":"Azot döngüsünde bazı mikroorganizmaların rolü nedir?","b":"Atmosferdeki serbest azotu, bitkilerin kullanabileceği bileşiklere dönüştürürler (azot bağlanması)."},{"f":"Su döngüsünün canlılar için önemi nedir?","b":"Suyun buharlaşma, yoğuşma ve yağış yoluyla sürekli dönmesi, canlıların ihtiyaç duyduğu suyun sürekliliğini sağlar."},{"f":"Ayrıştırıcı canlılara örnek ver, görevleri nedir?","b":"Bakteri ve mantarlar başlıca ayrıştırıcılardır; ölü organizma ve atıkları inorganik maddeye dönüştürerek madde döngüsüne katkı sağlar."},{"f":"Biyolojik birikim (biyoakümülasyon) nedir?","b":"Doğada kolay parçalanmayan zararlı maddelerin besin zinciri boyunca üst basamaklara çıkıldıkça giderek yoğunlaşarak birikmesidir."},{"f":"Küresel iklim değişikliğinin başlıca nedeni nedir?","b":"İnsan etkinlikleriyle atmosfere salınan sera gazlarının artmasıyla dünya ortalama sıcaklığının yükselmesidir."},{"f":"Asit yağmurlarına ne sebep olur?","b":"Fosil yakıtların yanmasıyla açığa çıkan kükürt ve azot oksitlerin atmosferdeki suyla birleşip asidik yağışa dönüşmesidir."},{"f":"Erozyon nedir?","b":"Toprağın rüzgâr, su gibi doğal etkenlerle aşınıp taşınmasıdır; bitki örtüsünün azalması erozyonu hızlandırır."},{"f":"Güncel çevre sorunlarına örnek ver (en az 4).","b":"Hava kirliliği, su kirliliği, toprak kirliliği, küresel iklim değişikliği, erozyon, orman yangınları, ses ve radyoaktif kirlilik."},{"f":"Ekolojik ayak izi neyi ifade eder?","b":"Bir kişinin ya da toplumun tükettiği kaynakları üretmek ve atıklarını yok etmek için gereken biyolojik verimli alanın ölçüsüdür."},{"f":"Karbon ayak izi neyi ölçer?","b":"Bir bireyin veya faaliyetin doğrudan ya da dolaylı olarak atmosfere saldığı sera gazı miktarını ölçer."},{"f":"Su ayak izi neyi ifade eder?","b":"Bir bireyin veya ürünün üretiminde ya da tüketiminde kullanılan toplam su miktarını gösteren ölçüttür."},{"f":"Endemik tür nedir?","b":"Sadece belirli bir bölgede doğal olarak yetişen, dünyanın başka hiçbir yerinde doğal yayılışı bulunmayan türdür."},{"f":"Gen bankalarının amacı nedir?","b":"Nesli tükenme tehlikesindeki türlerin tohum, sperm veya doku gibi genetik materyallerini saklayarak biyolojik çeşitliliği korumaktır."},{"f":"Sürdürülebilirlik ne anlama gelir?","b":"Doğal kaynakların, gelecek nesillerin ihtiyaçlarını karşılama yeteneğini tehlikeye atmadan kullanılmasıdır."},{"f":"Biyolojik çeşitliliğin azalmasının başlıca nedenleri nelerdir?","b":"Doğal yaşam alanlarının tahribi, kirlilik, aşırı avlanma/biyokaçakçılık ve iklim değişikliği başlıca nedenlerdir."},{"f":"Biyokaçakçılık nedir?","b":"Nesli tehlike altındaki bitki ve hayvan türlerinin veya parçalarının yasa dışı yollarla toplanıp ticaretinin yapılmasıdır."},{"f":"Bir ekosistemde meydana gelen bir değişiklik neden önemlidir?","b":"Ekosistemdeki canlı-cansız denge birbirine bağlı olduğundan, bir değişiklik zincirleme biçimde diğer bileşenleri de etkileyebilir."}]}]}];
